def figma_get_me(account_id, hydrate=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_get_me"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(status, account_row=None, extra=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": account_row.get("id") if isinstance(account_row, dict) else account_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("figma_request_logs.json", logs)

    def _enforce_rate_limit(account_row):
        # Best-effort, since no explicit schema provided; enforce conservative per-account limit if logs exist.
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        acct = account_row.get("id")
        window_s = 60
        limit = 120
        cnt = 0
        for r in reversed(logs):
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[A-Za-z0-9]+$", account_id):
        _audit("VALIDATION_ERROR", None, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "account_id is missing or invalid")

    if hydrate is not None and not isinstance(hydrate, bool):
        _audit("VALIDATION_ERROR", None, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "hydrate must be a boolean")
    if use_cache is not None and not isinstance(use_cache, bool):
        _audit("VALIDATION_ERROR", None, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "use_cache must be a boolean")

    hydrate = bool(hydrate) if hydrate is not None else False
    use_cache = bool(use_cache) if use_cache is not None else False

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _audit("NOT_FOUND", None, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Account not found")

    rl = _enforce_rate_limit(acct)
    if rl:
        _audit("RATE_LIMIT", acct, {"error_code": "RATE_LIMIT"})
        return rl

    # Auth: must have active token; if oauth and expires_at passed -> expired
    status = acct.get("status")
    token_type = acct.get("token_type")
    expires_at = _parse_dt(acct.get("expires_at"))
    if token_type == "oauth_access_token" and expires_at is not None:
        if datetime.datetime.utcnow() >= expires_at:
            # transition active->expired if allowed
            if status == "active":
                acct["status"] = "expired"
                acct["updated_at"] = _now_iso()
                acct["last_error"] = {"code": "TOKEN_EXPIRED", "message": "OAuth access token expired"}
                _save("figma_accounts.json", accounts)
            _audit("UNAUTHORIZED", acct, {"error_code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Stored token is expired")

    if status != "active":
        _audit("UNAUTHORIZED", acct, {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Stored token is not active")

    # Cache via snapshots (best-effort). Snapshot type "get_me".
    # Not declared in enum; store anyway if snapshots collection exists.
    snapshots = _load("figma_snapshots.json")
    if not isinstance(snapshots, list):
        snapshots = []
    params = {"account_id": account_id}
    fp = hashlib.sha256(json.dumps(params, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    if use_cache:
        for s in snapshots:
            if not isinstance(s, dict):
                continue
            if s.get("account_id") == account_id and s.get("snapshot_type") == "get_me" and s.get("request_fingerprint") == fp:
                if s.get("status") == "fresh":
                    exp = _parse_dt(s.get("expires_at"))
                    if exp is None or datetime.datetime.utcnow() < exp:
                        acct["last_validated_at"] = _now_iso()
                        acct["updated_at"] = _now_iso()
                        _save("figma_accounts.json", accounts)
                        _audit("OK", acct, {"served_from_cache": True})
                        return {
                            "data": s.get("payload"),
                            "meta": {"served_from_cache": True, "snapshot_id": s.get("id")}
                        }

    # Offline "Figma call": synthesize profile from existing account row (no fabrication beyond store)
    profile = {
        "id": acct.get("figma_user_id"),
        "handle": acct.get("handle"),
        "email": acct.get("email"),
        "img_url": acct.get("avatar_url"),
        "name": acct.get("display_name"),
    }

    now = _now_iso()
    acct["last_validated_at"] = now
    acct["updated_at"] = now
    acct["last_error"] = None
    # hydrate means "upsert by figma_user_id"; we already have it; enforce uniqueness best-effort
    if hydrate:
        fu = acct.get("figma_user_id")
        if not isinstance(fu, str) or not fu:
            _audit("VALIDATION_ERROR", acct, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Account figma_user_id is missing; cannot hydrate")
        # ensure no other row has same figma_user_id
        for other in accounts:
            if other is acct or not isinstance(other, dict):
                continue
            if other.get("figma_user_id") == fu:
                _audit("CONFLICT", acct, {"error_code": "CONFLICT"})
                return _err("CONFLICT", "Duplicate figma_user_id exists in catalog")
        # update profile fields from "fetched" profile (same source here)
        acct["handle"] = profile.get("handle")
        acct["email"] = profile.get("email")
        acct["display_name"] = profile.get("name")
        acct["avatar_url"] = profile.get("img_url")

    _save("figma_accounts.json", accounts)

    # store snapshot with short TTL
    snap_row = None
    ttl = datetime.timedelta(seconds=30)
    exp_iso = (datetime.datetime.utcnow() + ttl).replace(microsecond=0).isoformat() + "Z"
    # upsert by (account_id, snapshot_type, request_fingerprint) where status in fresh/stale
    existing = next((s for s in snapshots if isinstance(s, dict) and s.get("account_id") == account_id and s.get("snapshot_type") == "get_me" and s.get("request_fingerprint") == fp and s.get("status") in ("fresh", "stale")), None)
    if existing:
        existing["params"] = params
        existing["payload"] = profile
        existing["etag"] = None
        existing["fetched_at"] = now
        existing["expires_at"] = exp_iso
        existing["status"] = "fresh"
        existing["error"] = None
        existing["updated_at"] = now
        snap_row = existing
    else:
        snap_row = {
            "id": "fig_snap_" + uuid.uuid4().hex,
            "account_id": account_id,
            "resource_id": None,
            "snapshot_type": "get_me",
            "request_fingerprint": fp,
            "params": params,
            "payload": profile,
            "etag": None,
            "fetched_at": now,
            "expires_at": exp_iso,
            "status": "fresh",
            "error": None,
            "created_at": now,
            "updated_at": now,
        }
        snapshots.append(snap_row)
    _save("figma_snapshots.json", snapshots)

    _audit("OK", acct, {"served_from_cache": False})
    return {"data": profile, "meta": {"served_from_cache": False, "snapshot_id": snap_row.get("id")}}

def figma_get_file(account_id, file_key, version=None, ids=None, depth=None, plugin_data=None, branch_data=None, hydrate=None, snapshot=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_get_file"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "credential_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("figma_request_logs.json", logs)

    def _rate_limit_check(acct_id):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit = 120
        cnt = 0
        for r in reversed(logs[-3000:]):
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct_id:
                continue
            ts = _dt_parse(r.get("timestamp"))
            if not ts:
                continue
            if (now_dt - ts).total_seconds() <= window_s:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
            else:
                break
        return None

    # ---- validate inputs ----
    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[A-Za-z0-9]+$", account_id):
        _log("error", None, {"code": "VALIDATION_ERROR", "message": "Malformed account_id."})
        return _err("VALIDATION_ERROR", "Malformed account_id.")
    if not isinstance(file_key, str) or not file_key.strip():
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "file_key is required."})
        return _err("VALIDATION_ERROR", "file_key is required.")
    if version is not None and (not isinstance(version, str) or not version.strip()):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "version must be a non-empty string when provided."})
        return _err("VALIDATION_ERROR", "version must be a non-empty string when provided.")
    if ids is not None:
        if not isinstance(ids, list) or any((not isinstance(x, str) or not x) for x in ids):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "ids must be an array of strings."})
            return _err("VALIDATION_ERROR", "ids must be an array of strings.")
    if depth is not None:
        if not isinstance(depth, int) or depth < 0:
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "depth must be an integer >= 0."})
            return _err("VALIDATION_ERROR", "depth must be an integer >= 0.")
    if plugin_data is not None and (not isinstance(plugin_data, str) or not plugin_data.strip()):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "plugin_data must be a non-empty string when provided."})
        return _err("VALIDATION_ERROR", "plugin_data must be a non-empty string when provided.")
    if branch_data is not None and not isinstance(branch_data, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "branch_data must be a boolean."})
        return _err("VALIDATION_ERROR", "branch_data must be a boolean.")
    if hydrate is not None and not isinstance(hydrate, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "hydrate must be a boolean."})
        return _err("VALIDATION_ERROR", "hydrate must be a boolean.")
    if snapshot is not None and not isinstance(snapshot, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "snapshot must be a boolean."})
        return _err("VALIDATION_ERROR", "snapshot must be a boolean.")
    if use_cache is not None and not isinstance(use_cache, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "use_cache must be a boolean."})
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.")

    accounts = _load("figma_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("error", {"id": account_id}, {"code": "NOT_FOUND", "message": "Account not found."})
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)

    # enforce credential lifecycle rule
    if acct.get("status") in ("revoked", "expired"):
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Account credential is not active.", account_status=acct.get("status"))
    if acct.get("status") != "active":
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Account credential is not active.", account_status=acct.get("status"))

    rl = _rate_limit_check(account_id)
    if rl:
        _log("error", acct, {"code": "RATE_LIMIT", "message": rl["error"]["message"]})
        return rl

    # ---- ensure file resource exists/upsert ----
    resources = _load("figma_resources.json")
    now_iso = _iso_now()
    file_res = next((r for r in resources if isinstance(r, dict) and r.get("account_id") == account_id and r.get("resource_type") == "file" and r.get("figma_key") == file_key), None)
    if not file_res:
        file_res = {
            "id": "fig_res_" + uuid.uuid4().hex[:26],
            "account_id": account_id,
            "resource_type": "file",
            "figma_key": file_key,
            "parent_resource_id": None,
            "name": None,
            "description": None,
            "url": f"https://www.figma.com/file/{file_key}",
            "file_key": None,
            "team_id_key": None,
            "library_published_at": None,
            "raw_metadata": None,
            "status": "unknown",
            "last_synced_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        resources.append(file_res)
        _save("figma_resources.json", resources)
    elif hydrate:
        # best-effort "refresh"
        file_res["updated_at"] = now_iso
        file_res["last_synced_at"] = now_iso
        if file_res.get("status") == "unknown":
            file_res["status"] = "active"
        _save("figma_resources.json", resources)

    # ---- snapshots: serve cached if allowed ----
    snaps = _load("figma_snapshots.json")
    req_params = {
        "file_key": file_key,
        "version": version,
        "ids": ids,
        "depth": depth,
        "plugin_data": plugin_data,
        "branch_data": branch_data,
    }
    fp = hashlib.sha256(json.dumps(req_params, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode("utf-8")).hexdigest()
    snap_row = next((s for s in snaps if isinstance(s, dict) and s.get("account_id") == account_id and s.get("snapshot_type") == "get_file" and s.get("request_fingerprint") == fp and s.get("status") in ("fresh", "stale")), None)

    def _is_fresh(srow):
        if not srow or srow.get("status") != "fresh":
            return False
        exp = _dt_parse(srow.get("expires_at"))
        if exp and datetime.datetime.now(datetime.timezone.utc) > exp:
            return False
        return True

    if use_cache and not (snapshot is False) and _is_fresh(snap_row):
        payload = snap_row.get("payload")
        _log("ok", acct, None, {"source": "cache", "snapshot_id": snap_row.get("id")})
        return {
            "file": payload,
            "snapshot": {"id": snap_row.get("id"), "status": snap_row.get("status"), "fetched_at": snap_row.get("fetched_at"), "expires_at": snap_row.get("expires_at")},
            "meta": {"cached": True, "latency_ms": int((time.time() - t0) * 1000)}
        }

    # Offline backend: serve best available stored snapshot payload (fresh/stale) if present
    if snap_row and isinstance(snap_row.get("payload"), dict):
        payload = snap_row.get("payload")
        if snapshot:
            # update/refresh snapshot bookkeeping even when serving stored payload
            snap_row["updated_at"] = now_iso
            if snap_row.get("status") == "stale":
                snap_row["status"] = "fresh"
            snap_row["fetched_at"] = now_iso
            if snap_row.get("expires_at") is None:
                snap_row["expires_at"] = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=15)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            _save("figma_snapshots.json", snaps)
        _log("ok", acct, None, {"source": "snapshot_store", "snapshot_id": snap_row.get("id")})
        return {
            "file": payload,
            "snapshot": {"id": snap_row.get("id"), "status": snap_row.get("status"), "fetched_at": snap_row.get("fetched_at"), "expires_at": snap_row.get("expires_at")},
            "meta": {"cached": False, "latency_ms": int((time.time() - t0) * 1000)}
        }

    # No stored payload: return minimal document derived from local resource to avoid NOT_FOUND for valid call
    minimal = {
        "key": file_key,
        "name": file_res.get("name") or None,
        "lastModified": file_res.get("last_synced_at") or file_res.get("updated_at") or None,
        "thumbnailUrl": None,
        "version": version,
        "document": {"id": file_key, "name": file_res.get("name") or "Unknown", "type": "DOCUMENT"},
        "components": {},
        "componentSets": {},
        "styles": {},
        "schemaVersion": 0,
        "mainFileKey": file_key,
        "_offline": True,
    }

    if snapshot:
        # upsert snapshot row
        expires = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=15)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        if snap_row:
            snap_row["payload"] = minimal
            snap_row["etag"] = snap_row.get("etag")
            snap_row["fetched_at"] = now_iso
            snap_row["expires_at"] = expires
            snap_row["status"] = "fresh"
            snap_row["error"] = None
            snap_row["updated_at"] = now_iso
        else:
            # enforce uniqueness where status in fresh/stale (none exists here)
            snaps.append({
                "id": "fig_snap_" + uuid.uuid4().hex[:26],
                "account_id": account_id,
                "resource_id": file_res.get("id"),
                "snapshot_type": "get_file",
                "request_fingerprint": fp,
                "params": req_params,
                "payload": minimal,
                "etag": None,
                "fetched_at": now_iso,
                "expires_at": expires,
                "status": "fresh",
                "error": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            })
        _save("figma_snapshots.json", snaps)

    _log("ok", acct, None, {"source": "offline_minimal", "snapshot_written": bool(snapshot)})
    return {
        "file": minimal,
        "snapshot": None,
        "meta": {"cached": False, "latency_ms": int((time.time() - t0) * 1000)}
    }

