            if st == "deleted":
                continue
            # represent in a figma-like shape
            eligible.append({
                "id": c.get("figma_comment_id"),
                "message": c.get("message"),
                "client_meta": c.get("client_meta"),
                "order_id": c.get("order_id"),
                "created_by": {"id": c.get("created_by_figma_user_id")} if c.get("created_by_figma_user_id") else None,
                "resolved": c.get("resolved"),
                "created_at": c.get("figma_created_at"),
                "updated_at": c.get("figma_updated_at"),
                "parent_id": c.get("parent_figma_comment_id")
            })

        # stable ordering: order_id then created_at then id
        def _k(x):
            return (
                x.get("order_id") if isinstance(x.get("order_id"), int) else 10**18,
                x.get("created_at") or "",
                x.get("id") or ""
            )
        eligible.sort(key=_k)

        ps = page_size if page_size is not None else 100
        start = 0
        if cursor:
            # cursor is an integer offset encoded as string: "o:<n>"
            if not isinstance(cursor, str) or not cursor.startswith("o:"):
                _log("error", credential_id=acct.get("id"), error_code="VALIDATION_ERROR", error_message="cursor malformed.")
                return _err("VALIDATION_ERROR", "cursor is malformed.")
            try:
                start = int(cursor.split(":", 1)[1])
                if start < 0:
                    raise ValueError()
            except Exception:
                _log("error", credential_id=acct.get("id"), error_code="VALIDATION_ERROR", error_message="cursor malformed.")
                return _err("VALIDATION_ERROR", "cursor is malformed.")
        page = eligible[start:start + ps]
        next_cursor = None
        if start + ps < len(eligible):
            next_cursor = f"o:{start + ps}"

        served_payload = {"comments": page, "pagination": {"cursor": next_cursor, "has_more": next_cursor is not None}}
        served_from_cache = False
        served_snapshot_id = None
        served_fetched_at = now

        if snapshot:
            existing_snap = next((s for s in snapshots if isinstance(s, dict) and s.get("account_id") == account_id and s.get("snapshot_type") == snap_type and s.get("request_fingerprint") == fp and s.get("status") in ("fresh", "stale")), None)
            if existing_snap:
                existing_snap["payload"] = served_payload
                existing_snap["status"] = "fresh"
                existing_snap["error"] = None
                existing_snap["resource_id"] = file_id
                existing_snap["fetched_at"] = now
                existing_snap["expires_at"] = None
                existing_snap["updated_at"] = now
            else:
                snapshots.append({
                    "id": _new_id("fig_snap"),
                    "account_id": account_id,
                    "resource_id": file_id,
                    "snapshot_type": snap_type,
                    "request_fingerprint": fp,
                    "params": normalized_params,
                    "payload": served_payload,
                    "etag": None,
                    "fetched_at": now,
                    "expires_at": None,
                    "status": "fresh",
                    "error": None,
                    "created_at": now,
                    "updated_at": now
                })
            _save("figma_snapshots.json", snapshots)

    # Hydrate: upsert returned comments into catalog as synced (best-effort with local data)
    if hydrate:
        # Only hydrate if payload contains identifiable comments
        changed = False
        payload_comments = (served_payload or {}).get("comments") or []
        for pc in payload_comments:
            if not isinstance(pc, dict):
                continue
            fig_cid = pc.get("id")
            if fig_cid is None:
                continue
            existing_c = next((c for c in comments if isinstance(c, dict) and c.get("account_id") == account_id and c.get("file_resource_id") == file_res.get("id") and c.get("figma_comment_id") == fig_cid), None)
            if existing_c:
                # do not overwrite pending_delete
                if existing_c.get("status") != "pending_delete":
                    existing_c["status"] = "synced"
                existing_c["message"] = pc.get("message")
                existing_c["client_meta"] = pc.get("client_meta")
                existing_c["order_id"] = pc.get("order_id")
                existing_c["created_by_figma_user_id"] = ((pc.get("created_by") or {}) if isinstance(pc.get("created_by"), dict) else {}).get("id")
                existing_c["resolved"] = pc.get("resolved")
                existing_c["parent_figma_comment_id"] = pc.get("parent_id")
                existing_c["figma_created_at"] = pc.get("created_at")
                existing_c["figma_updated_at"] = pc.get("updated_at")
                existing_c["updated_at"] = now
                changed = True
            else:
                comments.append({
                    "id": _new_id("fig_cmt"),
                    "account_id": account_id,
                    "file_resource_id": file_res.get("id"),
                    "figma_comment_id": fig_cid,
                    "parent_figma_comment_id": pc.get("parent_id"),
                    "message": pc.get("message"),
                    "client_meta": pc.get("client_meta"),
                    "order_id": pc.get("order_id"),
                    "created_by_figma_user_id": ((pc.get("created_by") or {}) if isinstance(pc.get("created_by"), dict) else {}).get("id"),
                    "resolved": pc.get("resolved"),
                    "status": "synced",
                    "idempotency_key": None,
                    "last_error": None,
                    "figma_created_at": pc.get("created_at"),
                    "figma_updated_at": pc.get("updated_at"),
                    "created_at": now,
                    "updated_at": now
                })
                changed = True
        if changed:
            _save("figma_comments.json", comments)

    acct["last_validated_at"] = now
    acct["updated_at"] = now
    _save("figma_accounts.json", accounts)

    _log("ok", credential_id=acct.get("id"))
    return {
        "comments": (served_payload or {}).get("comments", []),
        "pagination": (served_payload or {}).get("pagination"),
        "from_cache": served_from_cache,
        "snapshot_id": served_snapshot_id,
        "fetched_at": served_fetched_at
    }

def figma_post_comment(account_id, file_key, message, idempotency_key, client_meta=None, parent_figma_comment_id=None, **_extra):
    import json, os, datetime, re, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_post_comment"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "credential_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex[:26]

    # ---- validate inputs ----
    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[A-Za-z0-9]+$", account_id):
        _log("error", None, {"code": "VALIDATION_ERROR", "message": "Malformed account_id.", "field": "account_id"})
        return _err("VALIDATION_ERROR", "Malformed account_id.", field="account_id")
    if not isinstance(file_key, str) or not file_key.strip():
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "file_key is required.", "field": "file_key"})
        return _err("VALIDATION_ERROR", "file_key is required.", field="file_key")
    if not isinstance(message, str) or len(message.strip()) < 1:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "message must be a non-empty string.", "field": "message"})
        return _err("VALIDATION_ERROR", "message must be a non-empty string.", field="message")
    if not isinstance(idempotency_key, str) or not idempotency_key.strip():
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "idempotency_key is required.", "field": "idempotency_key"})
        return _err("VALIDATION_ERROR", "idempotency_key is required.", field="idempotency_key")
    if client_meta is not None and not isinstance(client_meta, dict):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "client_meta must be an object.", "field": "client_meta"})
        return _err("VALIDATION_ERROR", "client_meta must be an object.", field="client_meta")
    if parent_figma_comment_id is not None and not isinstance(parent_figma_comment_id, str):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "parent_figma_comment_id must be a string.", "field": "parent_figma_comment_id"})
        return _err("VALIDATION_ERROR", "parent_figma_comment_id must be a string.", field="parent_figma_comment_id")

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("error", {"id": account_id}, {"code": "NOT_FOUND", "message": "Account not found.", "account_id": account_id})
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)

    # ---- enforce account active + expiry ----
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    exp = _dt_parse(acct.get("expires_at")) if acct.get("expires_at") else None
    if exp and exp <= now_dt:
        if acct.get("status") != "expired":
            acct["status"] = "expired"
            acct["updated_at"] = _iso_now()
            _save("figma_accounts.json", accounts)
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account access token expired.", "account_id": account_id})
        return _err("UNAUTHORIZED", "Account access token expired.", account_id=account_id)

    if acct.get("status") in ("revoked", "expired"):
        _log("error", acct, {"code": "UNAUTHORIZED", "message": f"Account credential is {acct.get('status')}.", "account_id": account_id})
        return _err("UNAUTHORIZED", f"Account credential is {acct.get('status')}.", account_id=account_id)
    if acct.get("status") != "active":
        _log("error", acct, {"code": "UNAUTHORIZED", "message": f"Account is not active (status={acct.get('status')}).", "account_id": account_id})
        return _err("UNAUTHORIZED", f"Account is not active (status={acct.get('status')}).", account_id=account_id)

    # ---- idempotency: unique per account across comments/reactions/webhooks ----
    comments = _load("figma_comments.json")
    if not isinstance(comments, list):
        comments = []
    reactions = _load("figma_comment_reactions.json")
    if not isinstance(reactions, list):
        reactions = []
    webhooks = _load("figma_webhooks.json")
    if not isinstance(webhooks, list):
        webhooks = []

    def _idem_hit():
        for c in comments:
            if isinstance(c, dict) and c.get("account_id") == account_id and c.get("idempotency_key") == idempotency_key:
                return ("comment", c)
        for r in reactions:
            if isinstance(r, dict) and r.get("account_id") == account_id and r.get("idempotency_key") == idempotency_key:
                return ("reaction", r)
        for w in webhooks:
            if isinstance(w, dict) and w.get("account_id") == account_id and w.get("idempotency_key") == idempotency_key:
                return ("webhook", w)
        return (None, None)

    kind, row = _idem_hit()
    if row is not None:
        # Return previously recorded outcome; do not duplicate mutation.
        _log("ok", acct, None, {"idempotency_replay": True, "kind": kind, "id": row.get("id")})
        return {"comment": row, "idempotency_key": idempotency_key, "replayed": True}

    # ---- upsert file resource ----
    resources = _load("figma_resources.json")
    if not isinstance(resources, list):
        resources = []

    file_res = next((r for r in resources if isinstance(r, dict)
                     and r.get("account_id") == account_id
                     and r.get("resource_type") == "file"
                     and r.get("figma_key") == file_key), None)
    now_iso = _iso_now()
    if not file_res:
        file_res = {
            "id": _new_id("fig_res"),
            "account_id": account_id,
            "resource_type": "file",
            "figma_key": file_key,
            "parent_resource_id": None,
            "name": None,
            "description": None,
            "url": f"https://www.figma.com/file/{file_key}",
            "file_key": None,
            "team_id_key": None,
            "library_published_at": None,
            "raw_metadata": None,
            "status": "unknown",
            "last_synced_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        resources.append(file_res)
        _save("figma_resources.json", resources)
    file_resource_id = file_res["id"]

    # ---- create local comment intent + simulate provider success (offline) ----
    # Must create with pending_create + non-null idempotency_key; then set synced with figma_comment_id on success.
    comment_id = _new_id("fig_cmt")
    # Deterministic-ish figma_comment_id from payload for stable retries (though idempotency already handled)
    figma_comment_id = str(int(hashlib.sha256((account_id + "|" + file_key + "|" + idempotency_key).encode("utf-8")).hexdigest()[:10], 16) % 2000000000 + 1000000000)

    pending_row = {
        "id": comment_id,
        "account_id": account_id,
        "file_resource_id": file_resource_id,
        "figma_comment_id": None,
        "parent_figma_comment_id": parent_figma_comment_id,
        "message": message,
        "client_meta": client_meta if client_meta is not None else {},
        "order_id": None,
        "created_by_figma_user_id": acct.get("figma_user_id"),
        "resolved": None,
        "status": "pending_create",
        "idempotency_key": idempotency_key,
        "last_error": None,
        "figma_created_at": None,
        "figma_updated_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    comments.append(pending_row)
    _save("figma_comments.json", comments)

    # "Provider call" result: in offline backend, mark as synced (successful creation)
    synced_row = pending_row
    synced_row["figma_comment_id"] = figma_comment_id
    synced_row["figma_created_at"] = now_iso
    synced_row["status"] = "synced"
    synced_row["updated_at"] = _iso_now()
    _save("figma_comments.json", comments)

    acct["last_validated_at"] = _iso_now()
    acct["updated_at"] = _iso_now()
    _save("figma_accounts.json", accounts)

    _log("ok", acct, None, {"comment_id": comment_id, "file_resource_id": file_resource_id})
    return {"comment": synced_row, "idempotency_key": idempotency_key}

def figma_delete_comment(account_id, file_key, comment_id, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, used_account_id=None, error=None, extra=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "fig_req_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": "figma_delete_comment",
            "account_id": used_account_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error is not None:
            row["error"] = error
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("figma_request_logs.json", logs)

    try:
        if not isinstance(account_id, str) or not re.match(r"^fig_acct_[0-9A-Z]{18,}$", account_id):
            _log("error", None, {"code": "VALIDATION_ERROR", "message": "Invalid account_id"})
            return _err("VALIDATION_ERROR", "Invalid account_id")
        if not isinstance(file_key, str) or len(file_key) < 1:
            _log("error", account_id, {"code": "VALIDATION_ERROR", "message": "file_key is required"})
            return _err("VALIDATION_ERROR", "file_key is required")
        if not isinstance(comment_id, str) or len(comment_id) < 1:
            _log("error", account_id, {"code": "VALIDATION_ERROR", "message": "comment_id is required"})
            return _err("VALIDATION_ERROR", "comment_id is required")
        if idempotency_key is not None and (not isinstance(idempotency_key, str) or len(idempotency_key) < 1):
            _log("error", account_id, {"code": "VALIDATION_ERROR", "message": "idempotency_key must be a non-empty string"})
            return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string")

        accounts = _load("figma_accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if not acct:
            _log("error", account_id, {"code": "UNAUTHORIZED", "message": "Account not found"})
            return _err("UNAUTHORIZED", "Account not found")
        if acct.get("status") != "active":
            _log("error", account_id, {"code": "UNAUTHORIZED", "message": "Account is not active", "status": acct.get("status")})
            return _err("UNAUTHORIZED", "Account is not active", status=acct.get("status"))

        # Global idempotency across comment/reaction/webhook mutations
        if idempotency_key is not None:
            comments = _load("figma_comments.json")
            if not isinstance(comments, list):
                comments = []
            reactions = _load("figma_comment_reactions.json")
            if not isinstance(reactions, list):
                reactions = []
            webhooks = _load("figma_webhooks.json")
            if not isinstance(webhooks, list):
                webhooks = []

            prior = next((c for c in comments if c.get("account_id") == account_id and c.get("idempotency_key") == idempotency_key), None)
            if prior is None:
                prior = next((r for r in reactions if r.get("account_id") == account_id and r.get("idempotency_key") == idempotency_key), None)
            if prior is None:
                prior = next((w for w in webhooks if w.get("account_id") == account_id and w.get("idempotency_key") == idempotency_key), None)

            if prior is not None:
                # Return previously recorded outcome without duplicating
                _log("ok", account_id, extra={"idempotency_replay": True})
                return {
                    "operation": prior,
                    "idempotency_replay": True,
                }

        resources = _load("figma_resources.json")
        if not isinstance(resources, list):
            resources = []

        # Upsert file resource
        file_res = next((r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "file" and r.get("figma_key") == file_key), None)
        if not file_res:
            file_res = {
                "id": "fig_res_" + uuid.uuid4().hex.upper(),
                "account_id": account_id,
                "resource_type": "file",
                "figma_key": file_key,
                "parent_resource_id": None,
                "name": None,
                "description": None,
                "url": None,
                "file_key": None,
                "team_id_key": None,
                "library_published_at": None,
                "raw_metadata": None,
                "status": "unknown",
                "last_synced_at": None,
                "created_at": now,
                "updated_at": now,
            }
            resources.append(file_res)
            _save("figma_resources.json", resources)

        # Validate file_resource_id points to a file
        file_resource_id = file_res["id"]

        comments = _load("figma_comments.json")
        if not isinstance(comments, list):
            comments = []

        # Find local comment row (by figma_comment_id) for this file
        comment_row = next((c for c in comments
                            if c.get("account_id") == account_id
                            and c.get("file_resource_id") == file_resource_id
                            and c.get("figma_comment_id") == comment_id), None)

        # If we already have it deleted, idempotent success
        if comment_row and comment_row.get("status") == "deleted":
            if idempotency_key is not None and not comment_row.get("idempotency_key"):
                comment_row["idempotency_key"] = idempotency_key
                comment_row["updated_at"] = now
                _save("figma_comments.json", comments)
            _log("ok", account_id, extra={"deleted": True, "idempotent": True})
            return {"deleted": True, "comment": comment_row, "idempotent": True}

        # If no local row, create an operation record to support retries/auditing
        if not comment_row:
            comment_row = {
                "id": "fig_cmt_" + uuid.uuid4().hex.upper(),
                "account_id": account_id,
                "file_resource_id": file_resource_id,
                "figma_comment_id": comment_id,
                "parent_figma_comment_id": None,
                "message": None,
                "client_meta": None,
                "order_id": None,
                "created_by_figma_user_id": None,
                "resolved": None,
                "status": "pending_delete",
                "idempotency_key": idempotency_key,
                "last_error": None,
                "figma_created_at": None,
                "figma_updated_at": None,
                "created_at": now,
                "updated_at": now,
            }
            comments.append(comment_row)
        else:
            # Transition synced/error -> pending_delete
            if comment_row.get("status") not in ("synced", "error", "pending_delete"):
                _log("error", account_id, {"code": "INVALID_TRANSITION", "message": "Comment cannot be deleted from its current status", "from_status": comment_row.get("status")})
                return _err("INVALID_TRANSITION", "Comment cannot be deleted from its current status", from_status=comment_row.get("status"))
            if comment_row.get("status") != "pending_delete":
                comment_row["status"] = "pending_delete"
            if idempotency_key is not None:
                comment_row["idempotency_key"] = idempotency_key
            comment_row["updated_at"] = now

        # Simulated Figma API delete: if account active, treat as success
        # On success: pending_delete -> deleted
        comment_row["status"] = "deleted"
        comment_row["last_error"] = None
        comment_row["updated_at"] = now

        _save("figma_comments.json", comments)

        acct["last_validated_at"] = now
        acct["updated_at"] = now
        _save("figma_accounts.json", accounts)

        _log("ok", account_id, extra={"deleted": True})
        return {"deleted": True, "comment": comment_row}
    except Exception as e:
        _log("error", account_id if isinstance(account_id, str) else None, {"code": "error", "message": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def figma_get_comment_reactions(account_id, file_key, comment_id, limit=None, cursor=None, hydrate=None, **_extra):
