                              and c.get("figma_comment_id") == comment_id), None)

        reactions = _load("figma_comment_reactions.json")
        if not isinstance(reactions, list):
            reactions = []

        # Figma "fetch" is represented by current local cache for this comment, if present.
        # If hydrate=True and comment exists, ensure all returned reactions are marked synced.
        # No blind deletes.
        matched = []
        if local_comment:
            for r in reactions:
                if r.get("account_id") == account_id and r.get("comment_id") == local_comment.get("id"):
                    if r.get("status") != "deleted":
                        matched.append(r)

            if hydrate:
                changed = False
                for r in matched:
                    if r.get("status") in ("error", "pending_create"):
                        r["status"] = "synced"
                        r["last_error"] = None
                        r["updated_at"] = now
                        changed = True
                if changed:
                    _save("figma_comment_reactions.json", reactions)

        # Pagination: cursor is an integer offset encoded as string
        offset = 0
        if cursor is not None:
            try:
                offset = int(cursor)
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log("error", account_id, {"code": "VALIDATION_ERROR", "message": "Invalid cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor")

        total = len(matched)
        page = matched[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = str(next_offset) if has_more else None

        acct["last_validated_at"] = now
        acct["updated_at"] = now
        _save("figma_accounts.json", accounts)

        _log("ok", account_id, extra={"total": total, "returned": len(page)})
        return {
            "reactions": page,
            "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "limit": limit},
        }
    except Exception as e:
        _log("error", account_id if isinstance(account_id, str) else None, {"code": "error", "message": str(e)})
