        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("figma_request_logs.json", logs)

    def _parse_cursor(c):
        # Expected internal format: "off:<int>"
        if c is None:
            return 0, None
        if not isinstance(c, str) or not c.strip():
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        m = re.match(r"^off:(\d+)$", c.strip())
        if not m:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")
        return int(m.group(1)), None

    def _account_ok(acct):
        if acct.get("status") != "active":
            # Business rule: expired/revoked must fail with auth error; set status appropriately.
            # If expires_at is in the past, mark expired; if revoked already, keep.
            st = acct.get("status")
            exp = acct.get("expires_at")
            if st not in ("revoked", "expired"):
                if exp:
                    try:
                        exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
                        if exp_dt <= datetime.datetime.now(datetime.timezone.utc):
                            st = "expired"
                        else:
                            st = "error"
                    except Exception:
                        st = "error"
                else:
                    st = "error"
            return False, st
        # If oauth token expired by expires_at, mark expired
        if acct.get("token_type") == "oauth_access_token" and acct.get("expires_at"):
            try:
                exp_dt = datetime.datetime.fromisoformat(acct["expires_at"].replace("Z", "+00:00"))
                if exp_dt <= datetime.datetime.now(datetime.timezone.utc):
                    return False, "expired"
            except Exception:
                return False, "error"
        return True, None

    # --- validation ---
    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[0-9A-Z]{18,}$", account_id):
        _log("error", error_code="VALIDATION_ERROR", error_message="invalid account_id format")
        return _err("VALIDATION_ERROR", "invalid account_id format")

    if not isinstance(team_id, str) or len(team_id) < 1:
        _log("error", error_code="VALIDATION_ERROR", error_message="team_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "team_id must be a non-empty string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 100")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    if hydrate is None:
        hydrate = False
    if not isinstance(hydrate, bool):
        _log("error", error_code="VALIDATION_ERROR", error_message="hydrate must be a boolean")
        return _err("VALIDATION_ERROR", "hydrate must be a boolean")

    offset, c_err = _parse_cursor(cursor)
