    if not ok:
        # write status update if needed
        if new_status and acct.get("status") != new_status:
            acct["status"] = new_status
            acct["updated_at"] = now
            _save("figma_accounts.json", accounts)
        _log("error", credential_id=acct.get("id"), error_code="UNAUTHORIZED", error_message="credential is not active")
        return _err("UNAUTHORIZED", "credential is not active", account_status=acct.get("status"))

    # --- resource validation/upsert for team ---
    resources = _load("figma_resources.json")
    if not isinstance(resources, list):
        resources = []

    team_res = next((r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "team" and r.get("figma_key") == team_id), None)
    if not team_res:
