            "raw_metadata": None,
            "status": "unknown",
            "last_synced_at": None,
            "created_at": now,
            "updated_at": now,
        }
        resources.append(team_res)
        _save("figma_resources.json", resources)

    # --- "Figma" listing served from local datastore ---
    # We treat figma_resources as our canonical catalog; team projects are projects whose parent is this team.
    projects_all = [r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "project" and r.get("parent_resource_id") == team_res.get("id") and r.get("status") != "deleted"]
    projects_all.sort(key=lambda r: ((r.get("name") or "").lower(), r.get("created_at") or "", r.get("id") or ""))

    total = len(projects_all)
    page = projects_all[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = ("off:%d" % next_off) if has_more else None

    # Hydrate: upsert returned projects into local catalog. Since we already read from catalog, ensure timestamps and unknown->active.
    if hydrate:
        changed = False
        ids_in_page = {p.get("id") for p in page if p.get("id")}
        for r in resources:
            if r.get("id") in ids_in_page:
                if r.get("status") == "unknown":
                    r["status"] = "active"
                    r["updated_at"] = now
                    changed = True
                if not r.get("team_id_key"):
                    r["team_id_key"] = team_id
                    r["updated_at"] = now
                    changed = True
        if changed:
            _save("figma_resources.json", resources)

    # Update account last_validated_at to reflect successful use
    acct["last_validated_at"] = now
    acct["updated_at"] = now
    _save("figma_accounts.json", accounts)

