            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": "figma_get_file_components",
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "created_at": now,
            "latency_ms": int((time.time() - started) * 1000),
        }
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("figma_request_logs.json", logs)

    def _parse_cursor(c):
        if c is None:
            return 0, None
        if not isinstance(c, str) or not c.strip():
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        m = re.match(r"^off:(\d+)$", c.strip())
        if not m:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")
        return int(m.group(1)), None

    def _account_ok(acct):
        if acct.get("status") != "active":
            st = acct.get("status")
            exp = acct.get("expires_at")
            if st not in ("revoked", "expired"):
                if exp:
                    try:
                        exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
                        if exp_dt <= datetime.datetime.now(datetime.timezone.utc):
                            st = "expired"
                        else:
                            st = "error"
                    except Exception:
                        st = "error"
                else:
                    st = "error"
            return False, st
        if acct.get("token_type") == "oauth_access_token" and acct.get("expires_at"):
            try:
                exp_dt = datetime.datetime.fromisoformat(acct["expires_at"].replace("Z", "+00:00"))
                if exp_dt <= datetime.datetime.now(datetime.timezone.utc):
                    return False, "expired"
            except Exception:
                return False, "error"
        return True, None

    # validation
    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[0-9A-Z]{18,}$", account_id):
        _log("error", error_code="VALIDATION_ERROR", error_message="invalid account_id format")
        return _err("VALIDATION_ERROR", "invalid account_id format")
    if not isinstance(file_key, str) or len(file_key) < 1:
        _log("error", error_code="VALIDATION_ERROR", error_message="file_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "file_key must be a non-empty string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 100")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    if hydrate is None:
        hydrate = False
    if not isinstance(hydrate, bool):
        _log("error", error_code="VALIDATION_ERROR", error_message="hydrate must be a boolean")
        return _err("VALIDATION_ERROR", "hydrate must be a boolean")

    offset, c_err = _parse_cursor(cursor)
    if c_err:
        _log("error", error_code=c_err["error"]["code"], error_message=c_err["error"]["message"])
        return c_err

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", error_code="UNAUTHORIZED", error_message="no such account_id")
        return _err("UNAUTHORIZED", "no active credential could be resolved for this request")

    ok, new_status = _account_ok(acct)
    if not ok:
        if new_status and acct.get("status") != new_status:
            acct["status"] = new_status
            acct["updated_at"] = now
            _save("figma_accounts.json", accounts)
        _log("error", credential_id=acct.get("id"), error_code="UNAUTHORIZED", error_message="credential is not active")
        return _err("UNAUTHORIZED", "credential is not active", account_status=acct.get("status"))

    resources = _load("figma_resources.json")
    if not isinstance(resources, list):
        resources = []

    # Ensure file resource exists
    file_res = next((r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "file" and r.get("figma_key") == file_key), None)
    if not file_res:
        file_res = {
            "id": "fig_res_" + uuid.uuid4().hex,
            "account_id": account_id,
            "resource_type": "file",
            "figma_key": file_key,
            "parent_resource_id": None,
            "name": None,
            "description": None,
            "url": None,
            "file_key": file_key,
            "team_id_key": None,
            "library_published_at": None,
            "raw_metadata": None,
            "status": "unknown",
            "last_synced_at": None,
            "created_at": now,
            "updated_at": now,
        }
        resources.append(file_res)
        _save("figma_resources.json", resources)

    comps_all = [
        r for r in resources
        if r.get("account_id") == account_id
        and r.get("resource_type") == "component"
        and r.get("status") != "deleted"
        and (r.get("parent_resource_id") == file_res.get("id") or r.get("file_key") == file_key)
    ]
    comps_all.sort(key=lambda r: ((r.get("name") or "").lower(), r.get("figma_key") or "", r.get("id") or ""))

    total = len(comps_all)
    page = comps_all[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = ("off:%d" % next_off) if has_more else None

    if hydrate:
        changed = False
        for r in page:
            # ensure file_key is set (constraint)
            if not r.get("file_key"):
                r["file_key"] = file_key
                r["updated_at"] = now
                changed = True
            # attach parent_resource_id to file when determinable
            if r.get("parent_resource_id") != file_res.get("id"):
                r["parent_resource_id"] = file_res.get("id")
                r["updated_at"] = now
                changed = True
            if r.get("status") == "unknown":
                r["status"] = "active"
                r["updated_at"] = now
                changed = True
        if changed:
            _save("figma_resources.json", resources)

    acct["last_validated_at"] = now
    acct["updated_at"] = now
    _save("figma_accounts.json", accounts)

    _log("ok", credential_id=acct.get("id"), meta={"returned": len(page), "total": total, "offset": offset, "limit": limit})

    return {
        "components": [
            {
                "component_key": r.get("figma_key"),
                "name": r.get("name"),
                "description": r.get("description"),
                "resource_id": r.get("id"),
                "file_key": file_key,
                "url": r.get("url"),
                "status": r.get("status"),
                "last_synced_at": r.get("last_synced_at"),
                "library_published_at": r.get("library_published_at"),
            } for r in page
        ],
        "page_info": {
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "limit": limit,
        }
    }

def figma_get_component(account_id, key, use_cache=None, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_get_component"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "credential_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    def _rate_limit_check(acct_id):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit = 120
        cnt = 0
        for r in reversed(logs[-3000:]):
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct_id:
                continue
            ts = _dt_parse(r.get("timestamp"))
            if not ts:
                continue
            if (now_dt - ts).total_seconds() <= window_s:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
            else:
                break
        return None

    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[0-9A-Z]{18,}$", account_id):
        _log("error", {"id": account_id} if isinstance(account_id, str) else None, {"code": "VALIDATION_ERROR", "message": "Invalid account_id format.", "field": "account_id"})
        return _err("VALIDATION_ERROR", "Invalid account_id format.", field="account_id")
    if not isinstance(key, str) or len(key) < 1:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Missing or empty component key.", "field": "key"})
        return _err("VALIDATION_ERROR", "Missing or empty component key.", field="key")
    if use_cache is not None and not isinstance(use_cache, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "use_cache must be a boolean.", "field": "use_cache"})
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.", field="use_cache")
    if refresh is not None and not isinstance(refresh, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "refresh must be a boolean.", "field": "refresh"})
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")

    accounts = _load("figma_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("error", {"id": account_id}, {"code": "NOT_FOUND", "message": "Account not found."})
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    if acct.get("status") in ("revoked", "expired"):
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Account credential is not active.", account_status=acct.get("status"))
    if acct.get("status") != "active":
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Account credential is not active.", account_status=acct.get("status"))

    rl = _rate_limit_check(account_id)
    if rl:
        _log("error", acct, {"code": "RATE_LIMIT", "message": rl["error"]["message"]})
        return rl

    resources = _load("figma_resources.json")
    snaps = _load("figma_snapshots.json")
    now_iso = _iso_now()

    # resolve existing resource (if any)
    res = next((r for r in resources if isinstance(r, dict) and r.get("account_id") == account_id and r.get("resource_type") == "component" and r.get("figma_key") == key), None)

    # snapshot behaviour: use_cache unless refresh
    req_params = {"key": key}
    fp = hashlib.sha256(json.dumps(req_params, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode("utf-8")).hexdigest()
    snap = next((s for s in snaps if isinstance(s, dict) and s.get("account_id") == account_id and s.get("snapshot_type") == "get_component" and s.get("request_fingerprint") == fp and s.get("status") in ("fresh", "stale")), None)

    def _is_fresh(srow):
        if not srow or srow.get("status") != "fresh":
            return False
        exp = _dt_parse(srow.get("expires_at"))
        if exp and datetime.datetime.now(datetime.timezone.utc) > exp:
            return False
        return True

    if refresh is not True and use_cache and _is_fresh(snap) and isinstance(snap.get("payload"), dict):
        _log("ok", acct, None, {"source": "cache", "snapshot_id": snap.get("id")})
        return {
            "component": snap.get("payload"),
            "snapshot": {"id": snap.get("id"), "status": snap.get("status"), "fetched_at": snap.get("fetched_at"), "expires_at": snap.get("expires_at")},
            "meta": {"cached": True, "latency_ms": int((time.time() - t0) * 1000)}
        }

    if refresh is not True and snap and isinstance(snap.get("payload"), dict):
        _log("ok", acct, None, {"source": "snapshot_store", "snapshot_id": snap.get("id")})
        return {
            "component": snap.get("payload"),
            "snapshot": {"id": snap.get("id"), "status": snap.get("status"), "fetched_at": snap.get("fetched_at"), "expires_at": snap.get("expires_at")},
            "meta": {"cached": False, "latency_ms": int((time.time() - t0) * 1000)}
        }

    # Offline: (re)build payload from local resource if present; otherwise create placeholder and upsert resource row
    if not res:
        res = {
            "id": "fig_res_" + uuid.uuid4().hex[:26],
            "account_id": account_id,
            "resource_type": "component",
            "figma_key": key,
            "parent_resource_id": None,
            "name": None,
            "description": None,
            "url": None,
            "file_key": "unknown",
            "team_id_key": None,
            "library_published_at": None,
            "raw_metadata": None,
            "status": "unknown",
            "last_synced_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        resources.append(res)
        _save("figma_resources.json", resources)
    else:
        res["updated_at"] = now_iso
        if res.get("status") == "unknown":
            res["status"] = "active"
        _save("figma_resources.json", resources)

    payload = {
        "key": key,
        "name": res.get("name") or "Unknown",
        "description": res.get("description"),
        "file_key": res.get("file_key"),
        "node_id": None,
        "_offline": True,
    }

    # persist snapshot always on refresh, and also when use_cache requested (best effort caching)
    if refresh or use_cache:
        expires = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=30)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        if snap:
            snap["payload"] = payload
            snap["fetched_at"] = now_iso
            snap["expires_at"] = expires
            snap["status"] = "fresh"
            snap["error"] = None
            snap["updated_at"] = now_iso
        else:
            snaps.append({
                "id": "fig_snap_" + uuid.uuid4().hex[:26],
                "account_id": account_id,
                "resource_id": res.get("id"),
                "snapshot_type": "get_component",
                "request_fingerprint": fp,
                "params": req_params,
                "payload": payload,
                "etag": None,
                "fetched_at": now_iso,
                "expires_at": expires,
                "status": "fresh",
                "error": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            })
        _save("figma_snapshots.json", snaps)

    _log("ok", acct, None, {"source": "offline_resource", "snapshot_written": bool(refresh or use_cache)})
    return {
        "component": payload,
        "snapshot": None,
        "meta": {"cached": False, "latency_ms": int((time.time() - t0) * 1000)}
    }

