        return None

    def _snapshot_fresh(s):
        if not isinstance(s, dict) or s.get("status") != "fresh":
            return False
        exp = _dt_parse(s.get("expires_at")) if s.get("expires_at") else None
        if exp is None:
            return True
        return exp > datetime.datetime.now(datetime.timezone.utc)

    snap = _find_snapshot()
    if use_cache and not refresh and snap and _snapshot_fresh(snap):
        payload = snap.get("payload") if isinstance(snap.get("payload"), dict) else {"component_sets": []}
        acct["last_validated_at"] = now_iso
        acct["updated_at"] = now_iso
        _save("figma_accounts.json", accounts)
        _log("ok", acct, None, {"served_from_cache": True, "snapshot_id": snap.get("id")})
        items = payload.get("component_sets") if isinstance(payload.get("component_sets"), list) else []
        return {
            "component_sets": items[:page_size],
            "cursor": payload.get("next_cursor"),
            "page_size": page_size,
            "total": len(items),
            "has_more": bool(payload.get("next_cursor")),
            "snapshot": {"id": snap.get("id"), "status": snap.get("status"), "fetched_at": snap.get("fetched_at"), "expires_at": snap.get("expires_at")},
        }

    # ---- offline "fetch": serve from local resources (component_set in this team)
    # best-effort mapping: match by account and team_id_key
    component_sets = [
        r for r in resources
        if isinstance(r, dict)
        and r.get("account_id") == account_id
        and r.get("resource_type") == "component_set"
        and (r.get("team_id_key") == team_id or (isinstance(r.get("raw_metadata"), dict) and str(r.get("raw_metadata", {}).get("team_id")) == str(team_id)))
        and r.get("status") != "deleted"
    ]

    # stable sort by name then id
    component_sets.sort(key=lambda x: ((x.get("name") or "").lower(), x.get("id") or ""))

    start = 0
    if cursor:
        m = re.match(r"^o:(\d+)$", cursor)
        if not m:
            _log("error", acct, {"code": "VALIDATION_ERROR", "message": "Invalid cursor format.", "field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor format.", field="cursor")
        start = int(m.group(1))
        if start < 0:
            start = 0

    page = component_sets[start:start + page_size]
    next_cursor = None
    if start + page_size < len(component_sets):
        next_cursor = f"o:{start + page_size}"

    payload = {
        "component_sets": [
            {
                "resource_id": r.get("id"),
                "key": r.get("figma_key"),
                "name": r.get("name"),
                "description": r.get("description"),
                "file_key": r.get("file_key"),
                "team_id": r.get("team_id_key"),
                "status": r.get("status"),
                "updated_at": r.get("updated_at"),
                "raw_metadata": r.get("raw_metadata"),
            } for r in page
        ],
        "next_cursor": next_cursor,
        "source": "offline_datastore",
    }

    # upsert snapshot (fresh) with short TTL
    expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=10)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    if snap:
        snap["resource_id"] = team_res.get("id")
        snap["params"] = {"team_id": team_id, "page_size": page_size, "cursor": cursor}
        snap["payload"] = payload
        snap["etag"] = None
        snap["fetched_at"] = now_iso
        snap["expires_at"] = expires_at
        snap["status"] = "fresh"
        snap["error"] = None
        snap["updated_at"] = now_iso
    else:
        snap = {
            "id": "fig_snp_" + uuid.uuid4().hex[:24],
            "account_id": account_id,
            "resource_id": team_res.get("id"),
            "snapshot_type": snap_type,
            "request_fingerprint": fp,
            "params": {"team_id": team_id, "page_size": page_size, "cursor": cursor},
            "payload": payload,
            "etag": None,
            "fetched_at": now_iso,
            "expires_at": expires_at,
            "status": "fresh",
            "error": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        snapshots.append(snap)
    _save("figma_snapshots.json", snapshots)

    acct["last_validated_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("figma_accounts.json", accounts)
    _log("ok", acct, None, {"served_from_cache": False, "snapshot_id": snap.get("id")})

    return {
        "component_sets": payload["component_sets"],
        "cursor": next_cursor,
        "page_size": page_size,
        "total": len(component_sets),
        "has_more": bool(next_cursor),
        "snapshot": {"id": snap.get("id"), "status": snap.get("status"), "fetched_at": snap.get("fetched_at"), "expires_at": snap.get("expires_at")},
    }

def figma_get_file_component_sets(account_id, file_key, page_size=None, cursor=None, use_cache=None, refresh=None, **_extra):
    import json, os, datetime, re, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_get_file_component_sets"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "credential_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    def _rate_limit_check(acct_id):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit = 120
        cnt = 0
        for r in reversed(logs[-3000:]):
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != acct_id:
                continue
            ts = _dt_parse(r.get("timestamp"))
            if not ts:
                continue
            if (now_dt - ts).total_seconds() <= window_s:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
            else:
                break
        return None

    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[0-9A-Z]{18,}$", account_id):
        _log("error", {"id": account_id} if isinstance(account_id, str) else None, {"code": "VALIDATION_ERROR", "message": "Invalid account_id format.", "field": "account_id"})
        return _err("VALIDATION_ERROR", "Invalid account_id format.", field="account_id")
    if not isinstance(file_key, str) or len(file_key) < 1:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Missing or empty file_key.", "field": "file_key"})
        return _err("VALIDATION_ERROR", "Missing or empty file_key.", field="file_key")
    if page_size is not None and (not isinstance(page_size, int) or page_size < 1 or page_size > 1000):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "page_size must be an integer between 1 and 1000.", "field": "page_size"})
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 1000.", field="page_size")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "cursor must be a string.", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if use_cache is not None and not isinstance(use_cache, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "use_cache must be a boolean.", "field": "use_cache"})
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.", field="use_cache")
    if refresh is not None and not isinstance(refresh, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "refresh must be a boolean.", "field": "refresh"})
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")

    accounts = _load("figma_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("error", {"id": account_id}, {"code": "NOT_FOUND", "message": "Account not found."})
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)
    if acct.get("status") in ("revoked", "expired"):
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Account credential is not active.", account_status=acct.get("status"))
    if acct.get("status") != "active":
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Account credential is not active.", account_status=acct.get("status"))

    rl = _rate_limit_check(account_id)
    if rl:
        _log("error", acct, {"code": "RATE_LIMIT", "message": rl["error"]["message"]})
        return rl

    resources = _load("figma_resources.json")
    snaps = _load("figma_snapshots.json")
    now_iso = _iso_now()

    # ensure file resource exists
    file_res = next((r for r in resources if isinstance(r, dict) and r.get("account_id") == account_id and r.get("resource_type") == "file" and r.get("figma_key") == file_key), None)
    if not file_res:
        file_res = {
            "id": "fig_res_" + uuid.uuid4().hex[:26],
            "account_id": account_id,
            "resource_type": "file",
            "figma_key": file_key,
            "parent_resource_id": None,
            "name": None,
            "description": None,
            "url": f"https://www.figma.com/file/{file_key}",
            "file_key": None,
            "team_id_key": None,
            "library_published_at": None,
            "raw_metadata": None,
            "status": "unknown",
            "last_synced_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        resources.append(file_res)
        _save("figma_resources.json", resources)

    # snapshot lookup
    req_params = {"file_key": file_key, "page_size": page_size, "cursor": cursor}
    fp = hashlib.sha256(json.dumps(req_params, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode("utf-8")).hexdigest()
    snap = next((s for s in snaps if isinstance(s, dict) and s.get("account_id") == account_id and s.get("snapshot_type") == "get_file_component_sets" and s.get("request_fingerprint") == fp and s.get("status") in ("fresh", "stale")), None)

    def _is_fresh(srow):
        if not srow or srow.get("status") != "fresh":
            return False
        exp = _dt_parse(srow.get("expires_at"))
        if exp and datetime.datetime.now(datetime.timezone.utc) > exp:
            return False
        return True

    if refresh is not True and use_cache and _is_fresh(snap) and isinstance(snap.get("payload"), dict):
        _log("ok", acct, None, {"source": "cache", "snapshot_id": snap.get("id")})
        return {
            "component_sets": snap.get("payload").get("component_sets", []),
            "next_cursor": snap.get("payload").get("next_cursor"),
            "meta": {"cached": True, "latency_ms": int((time.time() - t0) * 1000)}
        }

    # build from local resources
    all_sets = [r for r in resources if isinstance(r, dict) and r.get("account_id") == account_id and r.get("resource_type") == "component_set" and r.get("file_key") == file_key and r.get("status") != "deleted"]
    all_sets.sort(key=lambda x: (x.get("name") or "", x.get("figma_key") or ""))

    # cursor is an offset token "o:<int>" (provider-style cursors are opaque; accept any and treat unknown as 0)
    offset = 0
    if cursor:
        m = re.match(r"^o:(\d+)$", cursor.strip())
        if m:
            offset = int(m.group(1))
        else:
            # accept provider cursor shapes like "v:112" by ignoring and starting at 0
            offset = 0

    ps = page_size or 100
    page = all_sets[offset:offset + ps]
    next_cursor = None
    if offset + ps < len(all_sets):
        next_cursor = f"o:{offset + ps}"

    payload = {
        "component_sets": [
            {"key": r.get("figma_key"), "name": r.get("name"), "description": r.get("description"), "file_key": r.get("file_key")}
            for r in page
        ],
        "next_cursor": next_cursor,
        "_offline": True
    }

    # write snapshot on refresh or when requested to cache
    if refresh or use_cache:
        expires = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=30)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        if snap:
            snap["payload"] = payload
            snap["fetched_at"] = now_iso
            snap["expires_at"] = expires
            snap["status"] = "fresh"
            snap["error"] = None
            snap["updated_at"] = now_iso
        else:
            snaps.append({
                "id": "fig_snap_" + uuid.uuid4().hex[:26],
                "account_id": account_id,
                "resource_id": file_res.get("id"),
                "snapshot_type": "get_file_component_sets",
                "request_fingerprint": fp,
                "params": req_params,
                "payload": payload,
                "etag": None,
                "fetched_at": now_iso,
                "expires_at": expires,
                "status": "fresh",
                "error": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            })
        _save("figma_snapshots.json", snaps)

    _log("ok", acct, None, {"source": "local_resources", "snapshot_written": bool(refresh or use_cache), "count": len(payload["component_sets"])})
    return {
        "component_sets": payload["component_sets"],
        "next_cursor": payload["next_cursor"],
        "meta": {"cached": False, "latency_ms": int((time.time() - t0) * 1000)}
    }

