        "snapshot": {"id": snap.get("id"), "status": snap.get("status"), "fetched_at": snap.get("fetched_at"), "expires_at": snap.get("expires_at")},
    }

def figma_get_style(account_id, key, use_cache=None, refresh=None, **_extra):
    import json, os, datetime, time, re, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_get_style"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "credential_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    # validate
    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[0-9A-Z]{18,}$", account_id):
        _log("error", None, {"code": "VALIDATION_ERROR", "message": "Invalid account_id format.", "field": "account_id"})
        return _err("VALIDATION_ERROR", "Invalid account_id format.", field="account_id")
    if not isinstance(key, str) or len(key) < 1:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "key must be a non-empty string.", "field": "key"})
        return _err("VALIDATION_ERROR", "key must be a non-empty string.", field="key")
    if use_cache is not None and not isinstance(use_cache, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "use_cache must be a boolean.", "field": "use_cache"})
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.", field="use_cache")
    if refresh is not None and not isinstance(refresh, bool):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "refresh must be a boolean.", "field": "refresh"})
        return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")

    use_cache = True if use_cache is None else use_cache
    refresh = False if refresh is None else refresh

    accounts = _load("figma_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("error", {"id": account_id}, {"code": "NOT_FOUND", "message": "Account not found."})
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)

    # expire OAuth if needed
    if acct.get("token_type") == "oauth_access_token":
        exp = _dt_parse(acct.get("expires_at"))
        if exp is not None and exp <= datetime.datetime.now(datetime.timezone.utc):
            if acct.get("status") == "active":
                acct["status"] = "expired"
                acct["updated_at"] = _iso_now()
                _save("figma_accounts.json", accounts)

    if acct.get("status") != "active":
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Account credential is not active.", account_status=acct.get("status"))

    # rate limit
    logs = _load("figma_request_logs.json")
    if isinstance(logs, list):
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit = 120
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict) or r.get("account_id") != account_id:
                continue
            ts = _dt_parse(r.get("timestamp"))
            if not ts:
                continue
            if (now_dt - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= limit:
            _log("error", acct, {"code": "RATE_LIMIT", "message": "Rate limit exceeded."})
            return _err("RATE_LIMIT", "Rate limit exceeded.")

    resources = _load("figma_resources.json")
    snapshots = _load("figma_snapshots.json")
    if not isinstance(snapshots, list):
        snapshots = []
    now_iso = _iso_now()

    # Upsert style resource row (unique by account_id, resource_type, figma_key)
    style_res = next((r for r in resources if isinstance(r, dict) and r.get("account_id") == account_id and r.get("resource_type") == "style" and r.get("figma_key") == key), None)
    if not style_res:
        style_res = {
            "id": "fig_res_" + uuid.uuid4().hex[:24],
            "account_id": account_id,
            "resource_type": "style",
            "figma_key": key,
            "parent_resource_id": None,
            "name": None,
            "description": None,
            "url": None,
            "file_key": None,
            "team_id_key": None,
            "library_published_at": None,
            "raw_metadata": None,
            "status": "unknown",
            "last_synced_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        resources.append(style_res)
        _save("figma_resources.json", resources)

    def _fingerprint():
        norm = {"key": key}
        raw = json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(raw).hexdigest()

    snap_type = "get_style"
    fp = _fingerprint()

    def _find_snapshot():
        for s in snapshots:
            if not isinstance(s, dict):
                continue
            if s.get("account_id") == account_id and s.get("snapshot_type") == snap_type and s.get("request_fingerprint") == fp and s.get("status") in ("fresh", "stale"):
                return s
        return None

    def _snapshot_fresh(s):
        if not isinstance(s, dict) or s.get("status") != "fresh":
            return False
        exp = _dt_parse(s.get("expires_at")) if s.get("expires_at") else None
        if exp is None:
            return True
        return exp > datetime.datetime.now(datetime.timezone.utc)

    snap = _find_snapshot()
    if use_cache and not refresh and snap and _snapshot_fresh(snap):
        payload = snap.get("payload") if isinstance(snap.get("payload"), dict) else {}
        acct["last_validated_at"] = now_iso
        acct["updated_at"] = now_iso
        _save("figma_accounts.json", accounts)
        _log("ok", acct, None, {"served_from_cache": True, "snapshot_id": snap.get("id")})
        return {
            "style": payload.get("style") if isinstance(payload.get("style"), dict) else payload,
            "snapshot": {"id": snap.get("id"), "status": snap.get("status"), "fetched_at": snap.get("fetched_at"), "expires_at": snap.get("expires_at")},
            "resource": style_res,
        }

    # Offline "fetch": derive details from local resource (raw_metadata) without contacting Figma
    style_payload = {
        "key": style_res.get("figma_key"),
        "name": style_res.get("name"),
        "description": style_res.get("description"),
        "file_key": style_res.get("file_key"),
        "team_id": style_res.get("team_id_key"),
        "metadata": style_res.get("raw_metadata"),
        "resource_id": style_res.get("id"),
    }

    payload = {"style": style_payload, "source": "offline_datastore"}

    expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=10)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    if snap:
        snap["resource_id"] = style_res.get("id")
        snap["params"] = {"key": key}
        snap["payload"] = payload
        snap["etag"] = None
        snap["fetched_at"] = now_iso
        snap["expires_at"] = expires_at
        snap["status"] = "fresh"
        snap["error"] = None
        snap["updated_at"] = now_iso
    else:
        snap = {
            "id": "fig_snp_" + uuid.uuid4().hex[:24],
            "account_id": account_id,
            "resource_id": style_res.get("id"),
            "snapshot_type": snap_type,
            "request_fingerprint": fp,
            "params": {"key": key},
            "payload": payload,
            "etag": None,
            "fetched_at": now_iso,
            "expires_at": expires_at,
            "status": "fresh",
            "error": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        snapshots.append(snap)
    _save("figma_snapshots.json", snapshots)

    # touch resource sync times (best-effort)
    style_res["last_synced_at"] = now_iso
    style_res["updated_at"] = now_iso
    _save("figma_resources.json", resources)

    acct["last_validated_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("figma_accounts.json", accounts)
    _log("ok", acct, None, {"served_from_cache": False, "snapshot_id": snap.get("id")})

    return {
        "style": style_payload,
        "snapshot": {"id": snap.get("id"), "status": snap.get("status"), "fetched_at": snap.get("fetched_at"), "expires_at": snap.get("expires_at")},
        "resource": style_res,
    }

def figma_post_webhook(account_id, body, **_extra):
    import json, os, datetime, re, time, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_post_webhook"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "timestamp": _now(),
            "endpoint": endpoint,
            "account_id": account_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("figma_request_logs.json", logs)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _enforce_limits(credential_id):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            return None
        window_s = 60
        limit = 60  # tighter for mutations
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if r.get("account_id") != account_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if (now_dt - ts).total_seconds() <= window_s:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=limit, window_seconds=window_s)
        return None

    def _valid_https_url(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme == "https" and bool(p.netloc)
        except Exception:
            return False

    # Validate input
    try:
        if not isinstance(account_id, str) or not re.match(r"^fig_acct_[0-9A-Z]{18,}$", account_id or ""):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid account_id format.")
        if not isinstance(body, dict):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "body must be an object.")
        for req in ("team_id", "event_type", "endpoint_url"):
            if req not in body:
                _log("error", meta={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"body.{req} is required.")
        team_id = body.get("team_id")
        event_type = body.get("event_type")
        endpoint_url = body.get("endpoint_url")
        passcode = body.get("passcode")
        active = body.get("active")
        idempotency_key = body.get("idempotency_key")

        if not isinstance(team_id, str) or len(team_id) < 1:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "body.team_id must be a non-empty string.")
        if not isinstance(event_type, str) or len(event_type) < 1:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "body.event_type must be a non-empty string.")
        if not isinstance(endpoint_url, str) or not _valid_https_url(endpoint_url):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "body.endpoint_url must be a valid https URL.")
        if passcode is not None and (not isinstance(passcode, str) or len(passcode) < 1):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "body.passcode must be a non-empty string when provided.")
        if active is not None and not isinstance(active, bool):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "body.active must be a boolean when provided.")
        if idempotency_key is not None and (not isinstance(idempotency_key, str) or len(idempotency_key) < 1):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "body.idempotency_key must be a non-empty string when provided.")
    except Exception as e:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid parameters.", detail=str(e))

    accounts = _load("figma_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", meta={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Account not linked.")
    credential_id = acct.get("id")

    if acct.get("status") in ("revoked", "expired"):
        _log("error", credential_id=credential_id, meta={"error_code": "UNAUTHORIZED", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Figma credential is not active.", status=acct.get("status"))

    rl = _enforce_limits(credential_id)
    if rl:
        _log("error", credential_id=credential_id, meta={"error_code": rl["error"]["code"]})
        return rl

    now = _now()

    # Enforce idempotency uniqueness across comment/reaction/webhook mutations
    if idempotency_key is not None:
        comments = _load("figma_comments.json")
        if not isinstance(comments, list):
            comments = []
        if any(c.get("account_id") == account_id and c.get("idempotency_key") == idempotency_key for c in comments):
            _log("error", credential_id=credential_id, meta={"error_code": "CONFLICT", "idempotency_key": idempotency_key})
            return _err("CONFLICT", "Idempotency key already used for a comment mutation.", idempotency_key=idempotency_key)

        reactions = _load("figma_comment_reactions.json")
        if not isinstance(reactions, list):
            reactions = []
        if any(r.get("account_id") == account_id and r.get("idempotency_key") == idempotency_key for r in reactions):
            _log("error", credential_id=credential_id, meta={"error_code": "CONFLICT", "idempotency_key": idempotency_key})
            return _err("CONFLICT", "Idempotency key already used for a reaction mutation.", idempotency_key=idempotency_key)

        webhooks = _load("figma_webhooks.json")
        if not isinstance(webhooks, list):
            webhooks = []
        existing = next((w for w in webhooks if w.get("account_id") == account_id and w.get("idempotency_key") == idempotency_key), None)
        if existing:
            _log("ok_idempotent", credential_id=credential_id, meta={"idempotency_key": idempotency_key, "webhook_id": existing.get("id")})
            return {"webhook": existing, "meta": {"idempotent_replay": True}}

    # Upsert team resource (must be resource_type='team')
    resources = _load("figma_resources.json")
    if not isinstance(resources, list):
        resources = []
    team_row = next((r for r in resources if r.get("account_id") == account_id and r.get("resource_type") == "team" and r.get("figma_key") == team_id), None)
    if not team_row:
        team_row = {
            "id": "fig_res_" + uuid.uuid4().hex,
            "account_id": account_id,
            "resource_type": "team",
            "figma_key": team_id,
            "parent_resource_id": None,
            "name": None,
            "description": None,
            "url": None,
            "file_key": None,
            "team_id_key": team_id,
            "library_published_at": None,
            "raw_metadata": None,
            "status": "unknown",
            "last_synced_at": None,
            "created_at": now,
            "updated_at": now
        }
        resources.append(team_row)
        _save("figma_resources.json", resources)
    else:
        team_row["updated_at"] = now
        if team_row.get("resource_type") != "team":
            _log("error", credential_id=credential_id, meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "team_resource_id must reference a team resource.")
        _save("figma_resources.json", resources)

    webhooks = _load("figma_webhooks.json")
    if not isinstance(webhooks, list):
        webhooks = []

    # Enforce uniqueness: (account_id, team_resource_id, event_type, endpoint_url) where status in pending_create/synced/pending_update
    for w in webhooks:
        if w.get("account_id") != account_id:
            continue
        if w.get("team_resource_id") != team_row.get("id"):
            continue
        if w.get("event_type") != event_type:
            continue
        if w.get("endpoint_url") != endpoint_url:
            continue
        if w.get("status") in ("pending_create", "synced", "pending_update"):
            _log("error", credential_id=credential_id, meta={"error_code": "CONFLICT"})
            return _err("CONFLICT", "A webhook for this team/event_type/endpoint_url already exists.", webhook_id=w.get("id"))

    # Create local webhook record with pending_create and idempotency_key (server-generated if omitted)
    if idempotency_key is None:
        idempotency_key = "fig_idem_" + uuid.uuid4().hex

        # Re-check cross-collection uniqueness for generated key (extremely unlikely collision)
        comments = _load("figma_comments.json")
        if any(c.get("account_id") == account_id and c.get("idempotency_key") == idempotency_key for c in (comments if isinstance(comments, list) else [])):
            idempotency_key = "fig_idem_" + uuid.uuid4().hex
        reactions = _load("figma_comment_reactions.json")
        if any(r.get("account_id") == account_id and r.get("idempotency_key") == idempotency_key for r in (reactions if isinstance(reactions, list) else [])):
            idempotency_key = "fig_idem_" + uuid.uuid4().hex
        if any(w.get("account_id") == account_id and w.get("idempotency_key") == idempotency_key for w in webhooks):
            idempotency_key = "fig_idem_" + uuid.uuid4().hex

    new_id = "fig_wh_" + uuid.uuid4().hex
    new_row = {
        "id": new_id,
        "account_id": account_id,
        "team_resource_id": team_row.get("id"),
        "figma_webhook_id": None,
        "event_type": event_type,
        "endpoint_url": endpoint_url,
        "passcode_ciphertext": ("enc:" + passcode) if passcode is not None else None,
        "active": True if active is None else active,
        "status": "pending_create",
        "idempotency_key": idempotency_key,
        "last_error": None,
        "last_verified_at": None,
        "created_at": now,
        "updated_at": now
    }
    webhooks.append(new_row)
    _save("figma_webhooks.json", webhooks)

    # Offline: cannot call Figma, so mark as error (legal transition pending_create -> error), persist and return record.
    for i, w in enumerate(webhooks):
        if w.get("id") == new_id:
            webhooks[i]["status"] = "error"
            webhooks[i]["last_error"] = {"code": "OFFLINE", "message": "Cannot create webhook in Figma (offline mode)."}
            webhooks[i]["updated_at"] = _now()
            new_row = webhooks[i]
            break
    _save("figma_webhooks.json", webhooks)

    # Also set account status to error on failed use (best-effort)
    acct_idx = next((i for i, a in enumerate(accounts) if a.get("id") == account_id), None)
    if acct_idx is not None:
        if accounts[acct_idx].get("status") == "active":
            accounts[acct_idx]["status"] = "error"
        accounts[acct_idx]["last_error"] = {"code": "OFFLINE", "message": "Cannot reach Figma API in offline mode."}
        accounts[acct_idx]["updated_at"] = _now()
        _save("figma_accounts.json", accounts)

    _log("error", credential_id=credential_id, meta={"error_code": "UNAUTHORIZED", "offline": True, "webhook_id": new_id})
    return {
        "webhook": new_row,
        "meta": {
            "created_local": True,
            "remote_created": False,
            "offline": True
        }
    }

