            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    def _valid_https_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urlparse(u)
            return p.scheme == "https" and bool(p.netloc)
        except Exception:
            return False

