            return _err("VALIDATION_ERROR", "Malformed account_id.", field="account_id")

        # Accept non-matching webhook_id in practice (audits show misrouted id); treat as lookup key.
        if not isinstance(webhook_id, str) or not webhook_id.strip():
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Malformed webhook_id.", "field": "webhook_id"})
            return _err("VALIDATION_ERROR", "Malformed webhook_id.", field="webhook_id")

        if not isinstance(body, dict):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "body must be an object.", "field": "body"})
            return _err("VALIDATION_ERROR", "body must be an object.", field="body")

        # Validate known fields if present
        if "active" in body and body["active"] is not None and not isinstance(body["active"], bool):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "active must be boolean.", "field": "active"})
            return _err("VALIDATION_ERROR", "active must be boolean.", field="active")

        if "endpoint_url" in body and body["endpoint_url"] is not None and not _valid_https_url(body["endpoint_url"]):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "endpoint_url must be a valid https URL.", "field": "endpoint_url"})
            return _err("VALIDATION_ERROR", "endpoint_url must be a valid https URL.", field="endpoint_url")

        if "passcode" in body and body["passcode"] is not None and not isinstance(body["passcode"], str):
