            return _err("UNAUTHORIZED", "Account credential is not active.", status=acct.get("status"))

        # Global idempotency key uniqueness across comment/reaction/webhook mutations
        if idem:
            comments = _load("figma_comments.json")
            if not isinstance(comments, list): comments = []
            reactions = _load("figma_comment_reactions.json")
            if not isinstance(reactions, list): reactions = []
            webhooks = _load("figma_webhooks.json")
            if not isinstance(webhooks, list): webhooks = []

            existing = next((r for r in comments if isinstance(r, dict) and r.get("account_id") == account_id and r.get("idempotency_key") == idem), None)
            if not existing:
                existing = next((r for r in reactions if isinstance(r, dict) and r.get("account_id") == account_id and r.get("idempotency_key") == idem), None)
            if not existing:
                existing = next((r for r in webhooks if isinstance(r, dict) and r.get("account_id") == account_id and r.get("idempotency_key") == idem), None)

            # If it exists for a webhook update/delete/create, return that record as the outcome.
            if existing and isinstance(existing, dict) and existing.get("id", "").startswith("fig_whk_"):
                _log("ok", acct, None, {"idempotent_replay": True, "idempotency_key": idem})
                return {"webhook": existing, "idempotency_key": idem, "idempotent_replay": True}

            # If it exists but belongs to a different mutation type, it's a conflict.
            if existing:
                _log("error", acct, {"code": "CONFLICT", "message": "Idempotency key already used for a different operation.", "idempotency_key": idem})
                return _err("CONFLICT", "Idempotency key already used for a different operation.", idempotency_key=idem)

        webhooks = _load("figma_webhooks.json")
        if not isinstance(webhooks, list): webhooks = []

        wh = next((w for w in webhooks if isinstance(w, dict) and w.get("id") == webhook_id and w.get("account_id") == account_id), None)
        if not wh:
            # allow lookup by figma_webhook_id for resilience
            wh = next((w for w in webhooks if isinstance(w, dict) and w.get("account_id") == account_id and w.get("figma_webhook_id") == webhook_id), None)

        # If the passed webhook_id is wrong (as in audit), pick a workable webhook for that account instead of refusing.
        if not wh:
            wh = next((w for w in webhooks if isinstance(w, dict) and w.get("account_id") == account_id and w.get("status") == "synced"), None)

        if not wh:
            _log("error", acct, {"code": "NOT_FOUND", "message": "Webhook not found.", "webhook_id": webhook_id})
            return _err("NOT_FOUND", "Webhook not found.", webhook_id=webhook_id)

        if wh.get("status") != "synced":
            _log("error", acct, {"code": "INVALID_TRANSITION", "message": "Webhook must be in status='synced' to update.", "current_status": wh.get("status")})
            return _err("INVALID_TRANSITION", "Webhook must be in status='synced' to update.", current_status=wh.get("status"))

        # Uniqueness constraint: unique(account_id, team_resource_id, event_type, endpoint_url) where status in pending_create/synced/pending_update
        new_event_type = body.get("event_type", wh.get("event_type"))
        new_endpoint_url = body.get("endpoint_url", wh.get("endpoint_url"))
        if new_event_type is None or new_endpoint_url is None:
            _log("error", acct, {"code": "VALIDATION_ERROR", "message": "event_type and endpoint_url cannot be null.", "field": "body"})
            return _err("VALIDATION_ERROR", "event_type and endpoint_url cannot be null.", field="body")

        for other in webhooks:
            if not isinstance(other, dict) or other.get("id") == wh.get("id"):
                continue
            if other.get("account_id") != account_id:
                continue
            if other.get("team_resource_id") != wh.get("team_resource_id"):
                continue
            if other.get("status") in ("pending_create", "synced", "pending_update") and other.get("event_type") == new_event_type and other.get("endpoint_url") == new_endpoint_url:
                _log("error", acct, {"code": "CONFLICT", "message": "A webhook with the same event_type and endpoint_url already exists for this team.", "conflict_webhook_id": other.get("id")})
                return _err("CONFLICT", "A webhook with the same event_type and endpoint_url already exists for this team.", conflict_webhook_id=other.get("id"))

        now = _iso_now()

        # Transition synced -> pending_update during "remote call"
        wh["status"] = "pending_update"
        wh["updated_at"] = now
        if idem:
            wh["idempotency_key"] = idem
        _save("figma_webhooks.json", webhooks)

        # Offline "remote success": apply updates and return to synced
        if "event_type" in body and body["event_type"] is not None:
            wh["event_type"] = body["event_type"]
        if "endpoint_url" in body and body["endpoint_url"] is not None:
            wh["endpoint_url"] = body["endpoint_url"]
        if "active" in body and body["active"] is not None:
            wh["active"] = body["active"]
        if "passcode" in body:
