            if body["passcode"] is None:
                wh["passcode_ciphertext"] = None
            else:
                wh["passcode_ciphertext"] = "enc:v1:figma:whk_passcode:" + uuid.uuid4().hex

        wh["status"] = "synced"
        wh["last_error"] = None
        wh["updated_at"] = _iso_now()
        acct["last_validated_at"] = wh["updated_at"]
        acct["updated_at"] = wh["updated_at"]
        _save("figma_accounts.json", accounts)
        _save("figma_webhooks.json", webhooks)

        _log("ok", acct, None, {"webhook_id": wh.get("id"), "idempotency_key": idem})
        return {"webhook": wh, "idempotency_key": idem}
    except Exception as e:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Unexpected error.", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

