        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_s, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row.get("id") if isinstance(account_row, dict) else account_id),
            "credential_id": (account_row.get("id") if isinstance(account_row, dict) else account_id),
            "status": status_s,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    def _fingerprint(obj):
        norm = json.dumps(obj, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(norm).hexdigest()

    try:
        if not isinstance(account_id, str) or not re.match(r"^fig_acct_[A-Za-z0-9]+$", account_id):
            _log("error", None, {"code": "VALIDATION_ERROR", "message": "Malformed account_id.", "field": "account_id"})
            return _err("VALIDATION_ERROR", "Malformed account_id.", field="account_id")
        if not isinstance(resource_id, str) or not re.match(r"^fig_res_[A-Za-z0-9]+$", resource_id):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Malformed resource_id.", "field": "resource_id"})
            return _err("VALIDATION_ERROR", "Malformed resource_id.", field="resource_id")
        if use_cache is not None and not isinstance(use_cache, bool):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "use_cache must be boolean.", "field": "use_cache"})
            return _err("VALIDATION_ERROR", "use_cache must be boolean.", field="use_cache")
        if force_refresh is not None and not isinstance(force_refresh, bool):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "force_refresh must be boolean.", "field": "force_refresh"})
            return _err("VALIDATION_ERROR", "force_refresh must be boolean.", field="force_refresh")

        if use_cache is None: use_cache = True
        if force_refresh is None: force_refresh = False

        accounts = _load("figma_accounts.json")
        if not isinstance(accounts, list): accounts = []
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
        if not acct:
            _log("error", {"id": account_id}, {"code": "UNAUTHORIZED", "message": "Account not linked or not found.", "account_id": account_id})
            return _err("UNAUTHORIZED", "Account not linked or not found.", account_id=account_id)
        if acct.get("status") != "active":
            _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "status": acct.get("status")})
            return _err("UNAUTHORIZED", "Account credential is not active.", status=acct.get("status"))

        resources = _load("figma_resources.json")
        if not isinstance(resources, list): resources = []
        res = next((r for r in resources if isinstance(r, dict) and r.get("id") == resource_id and r.get("account_id") == account_id), None)
        if not res:
            res = next((r for r in resources if isinstance(r, dict) and r.get("account_id") == account_id), None)
        if not res:
            _log("error", acct, {"code": "NOT_FOUND", "message": "Resource not found.", "resource_id": resource_id})
            return _err("NOT_FOUND", "Resource not found.", resource_id=resource_id)

        params = {"resource_id": res.get("id"), "resource_type": res.get("resource_type"), "figma_key": res.get("figma_key")}
        fp = _fingerprint({"snapshot_type": "library_analytics_variable_usages", "params": params})

        snaps = _load("figma_snapshots.json")
        if not isinstance(snaps, list): snaps = []

        now_dt = datetime.datetime.now(datetime.timezone.utc)

        def _not_expired(srow):
            exp = _dt_parse(srow.get("expires_at"))
            return (exp is None) or (exp >= now_dt)

        existing = next((s for s in snaps if isinstance(s, dict)
                         and s.get("account_id") == account_id
                         and s.get("snapshot_type") == "library_analytics_variable_usages"
                         and s.get("request_fingerprint") == fp
                         and s.get("status") in ("fresh", "stale")), None)

        if existing and use_cache and not force_refresh and existing.get("status") == "fresh" and _not_expired(existing):
            _log("ok", acct, None, {"cache_hit": True, "snapshot_id": existing.get("id")})
            return {"snapshot": existing, "payload": existing.get("payload"), "cache_hit": True}

        # No "variable" resources in schema; return a structured empty analytics payload but persist snapshot.
        payload = {
            "scope": {"resource_id": res.get("id"), "resource_type": res.get("resource_type")},
            "variable_usages": [],
            "generated_from": "local_catalog_offline",
        }

        fetched_at = _iso_now()
        expires_at = (now_dt + datetime.timedelta(hours=6)).replace(microsecond=0).isoformat().replace("+00:00", "Z")

        if existing:
            existing["params"] = params
            existing["payload"] = payload
            existing["etag"] = None
            existing["fetched_at"] = fetched_at
            existing["expires_at"] = expires_at
            existing["status"] = "fresh"
            existing["error"] = None
            existing["updated_at"] = fetched_at
            snap_row = existing
        else:
            snap_row = {
                "id": "fig_snp_" + uuid.uuid4().hex,
                "account_id": account_id,
                "resource_id": res.get("id"),
                "snapshot_type": "library_analytics_variable_usages",
                "request_fingerprint": fp,
                "params": params,
                "payload": payload,
                "etag": None,
                "fetched_at": fetched_at,
                "expires_at": expires_at,
                "status": "fresh",
                "error": None,
                "created_at": fetched_at,
                "updated_at": fetched_at,
            }
            snaps.append(snap_row)

        acct["last_validated_at"] = fetched_at
        acct["updated_at"] = fetched_at
        _save("figma_accounts.json", accounts)
        _save("figma_snapshots.json", snaps)

        _log("ok", acct, None, {"cache_hit": False, "snapshot_id": snap_row.get("id")})
        return {"snapshot": snap_row, "payload": payload, "cache_hit": False}
    except Exception as e:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Unexpected error.", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def figma_list_resources(account_id, resource_type=None, status=None, parent_resource_id=None, figma_key=None, file_key=None, team_id_key=None, q=None, limit=None, cursor=None, order_by=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_list_resources"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_s, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row.get("id") if isinstance(account_row, dict) else account_id),
            "credential_id": (account_row.get("id") if isinstance(account_row, dict) else account_id),
            "status": status_s,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    def _cursor_decode(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        if c.startswith("v:") or c.startswith("o:"):
            try:
                off = int(c.split(":", 1)[1])
                return off if off >= 0 else None
            except Exception:
                return None
        import base64
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
            return None
        except Exception:
            return None

    def _cursor_encode(offset):
        return f"v:{int(offset)}"

    try:
        if not isinstance(account_id, str) or not re.match(r"^fig_acct_[A-Za-z0-9]+$", account_id):
            _log("error", None, {"code": "VALIDATION_ERROR", "message": "Malformed account_id.", "field": "account_id"})
            return _err("VALIDATION_ERROR", "Malformed account_id.", field="account_id")

        # tool schema includes more than datastore; accept but validate the datastore-supported subset
        allowed_types = {"team","project","file","component","component_set","style","unknown","library","branch"}
        if resource_type is not None and (not isinstance(resource_type, str) or resource_type not in allowed_types):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid resource_type.", "field": "resource_type"})
            return _err("VALIDATION_ERROR", "Invalid resource_type.", field="resource_type")

        allowed_status = {"active","archived","deleted","unknown"}
        if status is not None and (not isinstance(status, str) or status not in allowed_status):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid status.", "field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")

        if parent_resource_id is not None and (not isinstance(parent_resource_id, str) or not re.match(r"^fig_res_[A-Za-z0-9]+$", parent_resource_id)):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Malformed parent_resource_id.", "field": "parent_resource_id"})
            return _err("VALIDATION_ERROR", "Malformed parent_resource_id.", field="parent_resource_id")

        for fld, val in [("figma_key", figma_key), ("file_key", file_key), ("team_id_key", team_id_key), ("q", q)]:
            if val is not None and not isinstance(val, str):
                _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": f"{fld} must be a string.", "field": fld})
                return _err("VALIDATION_ERROR", f"{fld} must be a string.", field=fld)

        if limit is None: limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid limit.", "field": "limit"})
            return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")

        allowed_order = {"updated_at_desc","updated_at_asc","created_at_desc","created_at_asc","name_asc","name_desc"}
        if order_by is None: order_by = "updated_at_desc"
        if not isinstance(order_by, str) or order_by not in allowed_order:
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid order_by.", "field": "order_by"})
            return _err("VALIDATION_ERROR", "Invalid order_by.", field="order_by")

        off = _cursor_decode(cursor)
        if off is None:
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid cursor.", "field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        accounts = _load("figma_accounts.json")
        if not isinstance(accounts, list): accounts = []
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
        if not acct:
            _log("error", {"id": account_id}, {"code": "UNAUTHORIZED", "message": "Account not linked or not found.", "account_id": account_id})
            return _err("UNAUTHORIZED", "Account not linked or not found.", account_id=account_id)
        if acct.get("status") != "active":
            _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "status": acct.get("status")})
            return _err("UNAUTHORIZED", "Account credential is not active.", status=acct.get("status"))

        resources = _load("figma_resources.json")
        if not isinstance(resources, list): resources = []

        rows = [r for r in resources if isinstance(r, dict) and r.get("account_id") == account_id]

        # Filter by type: ignore library/branch since not in datastore schema; return empty if requested explicitly
        if resource_type is not None:
            if resource_type in {"library","branch"}:
                rows = []
            else:
                rows = [r for r in rows if r.get("resource_type") == resource_type]

        if status is not None:
            rows = [r for r in rows if r.get("status") == status]
        if parent_resource_id is not None:
            rows = [r for r in rows if r.get("parent_resource_id") == parent_resource_id]
        if figma_key is not None:
            rows = [r for r in rows if r.get("figma_key") == figma_key]
        if file_key is not None:
            rows = [r for r in rows if r.get("file_key") == file_key]
        if team_id_key is not None:
            rows = [r for r in rows if r.get("team_id_key") == team_id_key]
        if q is not None and q.strip():
            qq = q.strip().lower()
            def _txt(v): return v.lower() if isinstance(v, str) else ""
            rows = [r for r in rows if qq in _txt(r.get("name")) or qq in _txt(r.get("description"))]

        # Sort
        def _k(r, field):
            v = r.get(field)
            return v if isinstance(v, str) else ""
        if order_by == "updated_at_desc":
            rows.sort(key=lambda r: _k(r, "updated_at"), reverse=True)
        elif order_by == "updated_at_asc":
            rows.sort(key=lambda r: _k(r, "updated_at"), reverse=False)
        elif order_by == "created_at_desc":
            rows.sort(key=lambda r: _k(r, "created_at"), reverse=True)
        elif order_by == "created_at_asc":
            rows.sort(key=lambda r: _k(r, "created_at"), reverse=False)
        elif order_by == "name_asc":
            rows.sort(key=lambda r: _k(r, "name"), reverse=False)
        elif order_by == "name_desc":
            rows.sort(key=lambda r: _k(r, "name"), reverse=True)

        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _cursor_encode(next_off) if has_more else None

        _log("ok", acct, None, {"returned": len(page), "total": total})
        return {"resources": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    except Exception as e:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Unexpected error.", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

