        if description is not None and description != res.get("description"):
            res["description"] = description
            changed = True
        if url is not None and url != res.get("url"):
            res["url"] = url
            changed = True
        if raw_metadata is not None and raw_metadata != res.get("raw_metadata"):
            res["raw_metadata"] = raw_metadata
            changed = True

        if status is not None and status != res.get("status"):
            current = res.get("status")
            transitions = {
                "unknown": {"active","archived","deleted"},
                "active": {"archived","deleted"},
                "archived": {"active","deleted"},
                "deleted": set(),
            }
            if current not in transitions or status not in transitions[current]:
                _log("error", acct, {"code": "INVALID_TRANSITION", "message": "Illegal status transition.", "from_status": current, "to_status": status})
                return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=current, to_status=status)
            res["status"] = status
            changed = True

        if not changed:
            # No success without effect for mutations.
            _log("error", acct, {"code": "CONFLICT", "message": "No changes to apply."})
            return _err("CONFLICT", "No changes to apply.")

        res["updated_at"] = now
        _save("figma_resources.json", resources)

        acct["last_validated_at"] = now
        acct["updated_at"] = now
        _save("figma_accounts.json", accounts)

        _log("ok", acct, None, {"resource_id": resource_id})
        return {"resource": res}
    except Exception as e:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Unexpected error.", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def figma_list_comments(account_id, file_resource_id, status=None, resolved=None, created_by_figma_user_id=None, idempotency_key=None, limit=None, cursor=None, order_by=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_list_comments"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status_s, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row.get("id") if isinstance(account_row, dict) else account_id),
            "credential_id": (account_row.get("id") if isinstance(account_row, dict) else account_id),
            "status": status_s,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    def _cursor_decode(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        if c.startswith("v:") or c.startswith("o:"):
            try:
                off = int(c.split(":", 1)[1])
                return off if off >= 0 else None
            except Exception:
                return None
        import base64
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
            return None
        except Exception:
            return None

    def _cursor_encode(offset):
        return f"v:{int(offset)}"

    try:
        if not isinstance(account_id, str) or not re.match(r"^fig_acct_[A-Za-z0-9]+$", account_id):
            _log("error", None, {"code": "VALIDATION_ERROR", "message": "Malformed account_id.", "field": "account_id"})
            return _err("VALIDATION_ERROR", "Malformed account_id.", field="account_id")
        if not isinstance(file_resource_id, str) or not re.match(r"^fig_res_[A-Za-z0-9]+$", file_resource_id):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Malformed file_resource_id.", "field": "file_resource_id"})
            return _err("VALIDATION_ERROR", "Malformed file_resource_id.", field="file_resource_id")

        allowed_status = {"synced","pending_create","pending_delete","deleted","error"}
        if status is not None and (not isinstance(status, str) or status not in allowed_status):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid status.", "field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
        if resolved is not None and not isinstance(resolved, bool):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "resolved must be boolean.", "field": "resolved"})
            return _err("VALIDATION_ERROR", "resolved must be boolean.", field="resolved")
        if created_by_figma_user_id is not None and not isinstance(created_by_figma_user_id, str):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "created_by_figma_user_id must be a string.", "field": "created_by_figma_user_id"})
            return _err("VALIDATION_ERROR", "created_by_figma_user_id must be a string.", field="created_by_figma_user_id")
        if idempotency_key is not None and not isinstance(idempotency_key, str):
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "idempotency_key must be a string.", "field": "idempotency_key"})
            return _err("VALIDATION_ERROR", "idempotency_key must be a string.", field="idempotency_key")

        if limit is None: limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid limit.", "field": "limit"})
            return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")

        allowed_order = {"figma_created_at_desc","figma_created_at_asc","updated_at_desc","updated_at_asc","created_at_desc","created_at_asc"}
        if order_by is None: order_by = "figma_created_at_desc"
        if not isinstance(order_by, str) or order_by not in allowed_order:
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid order_by.", "field": "order_by"})
            return _err("VALIDATION_ERROR", "Invalid order_by.", field="order_by")

        off = _cursor_decode(cursor)
        if off is None:
            _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid cursor.", "field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        accounts = _load("figma_accounts.json")
        if not isinstance(accounts, list): accounts = []
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
        if not acct:
            _log("error", {"id": account_id}, {"code": "UNAUTHORIZED", "message": "Account not linked or not found.", "account_id": account_id})
            return _err("UNAUTHORIZED", "Account not linked or not found.", account_id=account_id)
        if acct.get("status") != "active":
            _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "status": acct.get("status")})
            return _err("UNAUTHORIZED", "Account credential is not active.", status=acct.get("status"))

        resources = _load("figma_resources.json")
        if not isinstance(resources, list): resources = []
        file_res = next((r for r in resources if isinstance(r, dict) and r.get("id") == file_resource_id and r.get("account_id") == account_id), None)
        if not file_res or file_res.get("resource_type") != "file":
            _log("error", acct, {"code": "VALIDATION_ERROR", "message": "file_resource_id must reference a figma_resources row with resource_type='file'.", "field": "file_resource_id"})
            return _err("VALIDATION_ERROR", "file_resource_id must reference a figma_resources row with resource_type='file'.", field="file_resource_id")

        comments = _load("figma_comments.json")
        if not isinstance(comments, list): comments = []

        rows = [c for c in comments if isinstance(c, dict) and c.get("account_id") == account_id and c.get("file_resource_id") == file_resource_id]
        if status is not None:
            rows = [c for c in rows if c.get("status") == status]
        if resolved is not None:
            rows = [c for c in rows if c.get("resolved") == resolved]
        if created_by_figma_user_id is not None:
            rows = [c for c in rows if c.get("created_by_figma_user_id") == created_by_figma_user_id]
        if idempotency_key is not None:
            rows = [c for c in rows if c.get("idempotency_key") == idempotency_key]

        def _k(r, field):
            v = r.get(field)
            return v if isinstance(v, str) else ""

        if order_by == "figma_created_at_desc":
            rows.sort(key=lambda r: _k(r, "figma_created_at"), reverse=True)
        elif order_by == "figma_created_at_asc":
            rows.sort(key=lambda r: _k(r, "figma_created_at"), reverse=False)
        elif order_by == "updated_at_desc":
            rows.sort(key=lambda r: _k(r, "updated_at"), reverse=True)
        elif order_by == "updated_at_asc":
            rows.sort(key=lambda r: _k(r, "updated_at"), reverse=False)
        elif order_by == "created_at_desc":
            rows.sort(key=lambda r: _k(r, "created_at"), reverse=True)
        elif order_by == "created_at_asc":
            rows.sort(key=lambda r: _k(r, "created_at"), reverse=False)

        total = len(rows)
        page = rows[off:off + limit]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _cursor_encode(next_off) if has_more else None

        _log("ok", acct, None, {"returned": len(page), "total": total})
        return {"comments": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    except Exception as e:
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Unexpected error.", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def figma_get_comment(account_id, comment_id, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "figma_get_comment"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, account_row=None, error=None, meta=None):
        logs = _load("figma_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "fig_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "account_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "credential_id": (account_row or {}).get("id") if isinstance(account_row, dict) else account_id,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
            "meta": meta or {},
        })
        _save("figma_request_logs.json", logs)

    if not isinstance(account_id, str) or not re.match(r"^fig_acct_[A-Za-z0-9]+$", account_id):
        _log("error", None, {"code": "VALIDATION_ERROR", "message": "Invalid account_id.", "field": "account_id"})
        return _err("VALIDATION_ERROR", "Invalid account_id.", field="account_id")
    if not isinstance(comment_id, str) or not re.match(r"^fig_cmt_[A-Za-z0-9]+$", comment_id):
        _log("error", {"id": account_id}, {"code": "VALIDATION_ERROR", "message": "Invalid comment_id.", "field": "comment_id"})
        return _err("VALIDATION_ERROR", "Invalid comment_id.", field="comment_id")

    accounts = _load("figma_accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("error", {"id": account_id}, {"code": "NOT_FOUND", "message": "Account not found."})
        return _err("NOT_FOUND", "Account not found.", account_id=account_id)

    # expire OAuth if needed
    if acct.get("token_type") == "oauth_access_token":
        exp = _dt_parse(acct.get("expires_at"))
        if exp is not None and exp <= datetime.datetime.now(datetime.timezone.utc):
            if acct.get("status") == "active":
                acct["status"] = "expired"
                acct["updated_at"] = _iso_now()
                _save("figma_accounts.json", accounts)

    if acct.get("status") != "active":
        _log("error", acct, {"code": "UNAUTHORIZED", "message": "Account credential is not active.", "account_status": acct.get("status")})
        return _err("UNAUTHORIZED", "Account credential is not active.", account_status=acct.get("status"))

    # rate limit
    logs = _load("figma_request_logs.json")
    if isinstance(logs, list):
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit_rl = 120
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict) or r.get("account_id") != account_id:
                continue
            ts = _dt_parse(r.get("timestamp"))
            if not ts:
                continue
            if (now_dt - ts).total_seconds() <= window_s:
                cnt += 1
            else:
                break
        if cnt >= limit_rl:
            _log("error", acct, {"code": "RATE_LIMIT", "message": "Rate limit exceeded."})
            return _err("RATE_LIMIT", "Rate limit exceeded.")

    comments = _load("figma_comments.json")
    cmt = next((c for c in comments if isinstance(c, dict) and c.get("id") == comment_id), None)
    if not cmt or cmt.get("account_id") != account_id:
        _log("error", acct, {"code": "NOT_FOUND", "message": "Comment not found.", "comment_id": comment_id})
        return _err("NOT_FOUND", "Comment not found.", comment_id=comment_id)

    acct["last_validated_at"] = _iso_now()
    acct["updated_at"] = acct["last_validated_at"]
    _save("figma_accounts.json", accounts)
    _log("ok", acct, None, {"comment_status": cmt.get("status")})

    return {"comment": cmt}

def figma_whoami(account_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0269000" if __import__("os").path.isdir("./environment_mix/0269000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            # accept trailing Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log_store():
        """
        Observability: best-effort request log collection.
        The schema does not declare it, but contract requires using it IF present.
        We'll persist to figma_request_log.json if it already exists, else do nothing.
        """
        path = os.path.join(_DB, "figma_request_log.json")
        try:
            exists = os.path.exists(path)
        except Exception:
            exists = False
        if not exists:
            return None, None
        return "figma_request_log.json", _load("figma_request_log.json")

    def _append_log(log_name, logs, row):
        if log_name is None:
            return
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save(log_name, logs)

    started = time.time()
    log_name, logs = _ensure_request_log_store()
    log_row = {
        "id": None,
        "endpoint": "figma_whoami",
        "timestamp": _now_iso(),
        "account_id": account_id,
        "status": "error",
        "latency_ms": None,
    }

    try:
        # Validate inputs
        if account_id is not None:
            if not isinstance(account_id, str):
                log_row["status"] = "validation_error"
                return _err("VALIDATION_ERROR", "account_id must be a string")
            if not re.match(r"^fig_acct_[A-Za-z0-9]+$", account_id):
                log_row["status"] = "validation_error"
                return _err("VALIDATION_ERROR", "account_id does not match required pattern")

        accounts = _load("figma_accounts.json")
        if not isinstance(accounts, list):
            accounts = []

        # Resolve an account
        resolved = None
        if account_id is not None:
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == account_id:
                    resolved = a
                    break
            if resolved is None:
                log_row["status"] = "not_found"
                return _err("NOT_FOUND", "Figma account not found", account_id=account_id)
        else:
            # Ambient auth: find any account that can serve the call (active & not expired by time)
            # Choose most recently validated/updated.
            candidates = []
            now = datetime.datetime.now(datetime.timezone.utc)
            for a in accounts:
                if not isinstance(a, dict):
                    continue
                status = a.get("status")
                if status != "active":
                    continue
                # For OAuth tokens, enforce expires_at if present
                exp = _parse_dt(a.get("expires_at"))
                if exp is not None and exp <= now:
                    continue
                candidates.append(a)

            def _sort_key(a):
                lv = _parse_dt(a.get("last_validated_at"))
                up = _parse_dt(a.get("updated_at"))
                cr = _parse_dt(a.get("created_at"))
                return (lv or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
                        up or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
                        cr or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))

            if candidates:
                candidates.sort(key=_sort_key, reverse=True)
                resolved = candidates[0]

        if resolved is None:
            # No valid credential available
            log_row["status"] = "unauthorized"
            return _err("UNAUTHORIZED", "No valid Figma credential available for caller")

        # Enforce account status + update if expired by time
        now = datetime.datetime.now(datetime.timezone.utc)
        status = resolved.get("status")
        token_type = resolved.get("token_type")
        exp = _parse_dt(resolved.get("expires_at"))

        if token_type == "oauth_access_token" and exp is not None and exp <= now and status == "active":
            # mark expired
            allowed = {"active": {"expired", "revoked", "error"}}
            if "expired" in allowed.get("active", set()):
                resolved["status"] = "expired"
                resolved["updated_at"] = _now_iso()
                resolved["last_error"] = {"code": "TOKEN_EXPIRED", "message": "OAuth access token expired", "at": _now_iso()}
                # persist
                for i, a in enumerate(accounts):
                    if isinstance(a, dict) and a.get("id") == resolved.get("id"):
                        accounts[i] = resolved
                        break
                _save("figma_accounts.json", accounts)
                status = "expired"

        if status in ("expired", "revoked"):
            log_row["status"] = "unauthorized"
            return _err("UNAUTHORIZED", "Credential is not active", account_status=status, account_id=resolved.get("id"))

        if status not in ("active", "error"):
            # Shouldn't happen given lifecycle; treat as unauthorized
            log_row["status"] = "unauthorized"
            return _err("UNAUTHORIZED", "No valid Figma credential available for caller")

        # Rate/quota consumption: best-effort, based on figma_request_log.json if present.
        rate = {
            "window_seconds": 60,
            "limit": None,
            "used": 0,
            "remaining": None,
            "reset_at": None,
        }
        quota = {
            "period": "day",
            "limit": None,
            "used": 0,
            "remaining": None,
            "reset_at": None,
        }

        if log_name is not None:
            # compute last 60s usage for this account
            acct_id = resolved.get("id")
            window = datetime.timedelta(seconds=60)
            cutoff = now - window
            used_60 = 0
            used_day = 0
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            for r in (logs or []):
                if not isinstance(r, dict):
                    continue
                if r.get("account_id") != acct_id:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts is None:
                    continue
                if ts >= cutoff:
                    used_60 += 1
                if ts >= day_start:
                    used_day += 1
            rate["used"] = used_60
            rate["reset_at"] = (cutoff + window).isoformat()
            quota["used"] = used_day
            quota["reset_at"] = (day_start + datetime.timedelta(days=1)).isoformat()

        body = {
            "identity": {
                "account_id": resolved.get("id"),
                "figma_user_id": resolved.get("figma_user_id"),
                "handle": resolved.get("handle"),
                "email": resolved.get("email"),
                "display_name": resolved.get("display_name"),
                "avatar_url": resolved.get("avatar_url"),
            },
            "credential": {
                "token_type": resolved.get("token_type"),
                "status": resolved.get("status"),
                "scopes": resolved.get("scopes") if isinstance(resolved.get("scopes"), list) else [],
                "expires_at": resolved.get("expires_at"),
                "last_validated_at": resolved.get("last_validated_at"),
                "updated_at": resolved.get("updated_at"),
            },
            "consumption": {
                "rate_limit": rate,
                "quota": quota,
            },
        }

        log_row["status"] = "ok"
        return body

    except (TypeError, ValueError) as e:
        log_row["status"] = "validation_error"
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))
    except Exception as e:
        # Per contract: do not blanket-convert programming bugs; but we must not raise.
        log_row["status"] = "error"
        return _err("CONFLICT", "Unexpected server error", detail=str(e))
    finally:
        log_row["latency_ms"] = int((time.time() - started) * 1000)
        if log_name is not None:
            # generate a stable-ish id
            try:
                rid = f"fig_req_{int(time.time()*1000)}"
            except Exception:
                rid = None
            log_row["id"] = rid
            _append_log(log_name, logs, log_row)
